export default [{"id":193,"question":"ما العلة في كون لحم الإبل ينقض الوضوء؟","title":"ما العلة في نقض لحم الإبل الوضوء؟","answer":"الجواب: الله أعلم، الله جلَّ وعلا أعلم، وهو الرحيم والحكيم، لا يأمر إلا بما فيه حكمة، ولا ينهى إلا عمَّا فيه حكمة : إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ [الأنعام:83]، والنبي ﷺ قال: توضَّؤوا من لحوم الإبل، ولاا توضَّؤوا من لحوم الغنم، وقال ﷺ لما سُئل: أنتوضأ من لحوم الإبل؟ قال: نعم، فقيل: أنتوضأ من لحوم الغنم؟ قال: إن شئتَ، فيكفينا أن الرسول أمرنا بالوضوء، هذا كافينا، أما الحكمة فالله أعلم.","link":"https://binbaz.org.sa/fatwas/3768/ما-العلة-في-نقض-لحم-الابل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0199.mp3","categories":["نواقض الوضوء"]},{"id":195,"question":"ما الحكم فيمَن قبَّل امرأته وهو على طهارةٍ يُريد الصلاة؟","title":"هل تقبيل الزوجة ينقض الوضوء؟","answer":"الجواب: لا شيء عليه، إذا قبَّل زوجته ولم يخرج منه شيءٌ فوضوؤه صحيحٌ على الصحيح. وذهب بعضُ أهل العلم إلى أن تقبيلها ينقض الوضوء، وقال بعضُهم: مجرد اللمس ينقض الوضوء. والصواب أنه لا ينقض الوضوء على الأرجح من أقوال العلماء: أن مسَّ المرأة أو تقبيلها لا ينقض الوضوء، إذا لم يخرج منه شيءٌ، لا مذي، ولا غيره.","link":"https://binbaz.org.sa/fatwas/3788/هل-تقبيل-الزوجة-ينقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0201.mp3","categories":["نواقض الوضوء"]},{"id":476,"question":"هل يقال أن الوضوء من لحوم الغنم سُنة، عفا الله عنك؟","title":"حكم الوضوء من لحوم الغنم","answer":"الجواب: انعم، لقوله ﷺ: إن شئت؛ ولأنه كان أمر بالوضوء مما مست النار، ثم ترك ذلك؛ دل على أن الأمر ليس للوجوب، بل للاستحباب.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6232/حكم-الوضوء-من-لحوم-الغنم","audio":"https://files.zadapps.info/binbaz.org.sa/wadoa036.mp3","categories":["نواقض الوضوء"]},{"id":479,"question":"مس العورة ما يقتضي أنه يتوضأ؟","title":"حكم مس العورة للمتوضئ","answer":"الجواب: لا، الواجب ألا يمسها إلا من وراء حائل.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6237/حكم-مس-العورة-للمتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/3ora039.mp3","categories":["نواقض الوضوء"]},{"id":481,"question":"ما الحكمة من الوضوء من لحوم الإبل؟","title":"ما الحكمة من الوضوء من لحوم الإبل؟","answer":"الجواب: الله أعلم، علينا أن نمتثل ما قاله الرسول ﷺ، والحمد لله، وهو لا يقول إلا عن حكمة.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6240/ما-الحكمة-من-الوضوء-من-لحوم-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/la7m042.mp3","categories":["نواقض الوضوء"]},{"id":482,"question":"عفا الله عنك، هناك من يقول بأنه لم يأت حديث صحيح يدل على أن الدم ينقض الوضوء؟","title":"هل ينتقض الوضوء بخروج الدم؟","answer":"الجواب: ولهذا جرى الخلاف، لكن قول النبي ﷺ للمستحاضة: توضئي لكل صلاة، وهو دم عرق، وليس بدم حيض؛ هذا هو وجه الشبهة لمن قال بنقض الوضوء، لأنه قال لها: إنما هو دم عرق.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6241/هل-ينتقض-الوضوء-بخروج-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/dam043.mp3","categories":["نواقض الوضوء"]},{"id":483,"question":"القيء هل ينقض الوضوء؟","title":"هل القيء ينقض الوضوء؟","answer":"الجواب: فيه خلاف، لكن الأحوط الوضوء إذا كثير وتكرر.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6242/هل-القيء-ينقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/kaeaa044.mp3","categories":["نواقض الوضوء"]},{"id":728,"question":"هل إفرازات المرأة الطبيعية تنقض الوضوء للصلاة؟","title":"هل إفرازات المرأة الطبيعية تنقض الوضوء؟","answer":"الجواب: الإفرازات التي تخرج من المرأة حكمها حكم بقية ما يخرج من السَّبيلين، والقاعدة عند أهل العلم: أنَّ ما خرج من السَّبيلين من دبرٍ أو قُبُلٍ من أشياء ينقض الوضوء: البول، والغائط، والمذي، والودي، كل ذلك ينقض الوضوء، وهكذا الدم، مثل: دم الاستحاضة، وهكذا المياه التي تخرج من فرجها، كل هذا يُسمَّى: ناقضًا من نواقض الوضوء.\nوإذا استمرَّ معها صارت مثل المستحاضة، مثل صاحب السلس، تتوضأ لوقت كل صلاةٍ وتُصلي على حسب حالها ولو خرج، إذا كان الماء مُستمرًّا معها، إذا دخل وقتُ صلاة الفجر توضأت وصلَّت ولو خرج منها، وهكذا الظهر، وهكذا العصر، وهكذا المغرب، وهكذا العشاء، تتوضأ إذا دخل الوقتُ كالمستحاضة التي يستمر معها الدم، وتُصلي على حسب حالها والحمد لله.\nوينبغي أن تتحفظ بشيءٍ من قطنٍ ونحوه، إذا استنجت تتحفظ بشيءٍ حتى لا يخرج، وإذا استعملت المناديل قبل الوضوء بدلًا من الماء -إذا كان قد يشقّ عليها الماء- فالمناديل تكفي، إذا تنشفت بالمناديل ثلاث مراتٍ فأكثر حتى تُنقي المحلَّ، ثم توضأت وضوء الصلاة: بغسل الوجه واليدين إلى آخره؛ كفى ذلك، وهي بهذا يكون لها حكمُ المستحاضة إذا استمرَّ معها هذا الشيء وكثر ولم ينقطع.","link":"https://binbaz.org.sa/fatwas/20627/هل-افرازات-المراة-الطبيعية-تنقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0557هل افرازات المرأة الطبيعية تنقض الوضوء للصلاة؟ فتاوى المحاضرات.mp3","categories":["نواقض الوضوء"]},{"id":874,"question":"ما حكم وضوء مريض يخرج من دبره سائلٌ لزج في كل وقتٍ؟","title":"حكم طهارة من يخرج من دُبُره سائلٌ لزج","answer":"الجواب: حكمه حكم المستحاضة وصاحب السلس، يتوضأ لكل صلاةٍ إذا كان يخرج من دبره أو من ذكره شيء سائل، فإذا دخل الوقتُ يستنجي ويتحفظ بشيءٍ: قطن أو غيره، ثم يتوضأ وضوء الصلاة إلى الوقت الآخر، وهكذا في الفجر يتوضأ ثم يُصلي ويقرأ القرآن، ويقرأ من المصحف حتى يخرج الوقت وتطلع الشمس، وفي الظهر يتوضأ حتى يجيء وقتُ العصر، وفي العصر حتى يجيء وقت المغرب، وهكذا؛ لقول النبي ﷺ للمُستحاضة: توضَّئي لكل صلاةٍ، هذا مثلها، صاحب السلس في الذكر، أو في الدبر، هو مثلها.\nس: يُغير لباسه الدَّاخلي؟\nالشيخ: ما أصاب لباسه يغسله إذا استطاع ذلك، يغسل ذلك، أو يُغير اللباس كل وقتٍ.\nس: إذا كان يستوجب الأمر إلى أن يكون في دبره بعض الأدوية -كالمراهم مثلًا- خاصَّةً أن يكون عنده بواسير، أو بعض الأشياء الأخرى، فهل ..؟\nالشيخ: يتمسَّح بالمناديل، ما يحتاج شيئًا.\nس: لكن هل يُعتبر خروجه نجسًا أيضًا وهو يُدخله طاهرًا؟\nالشيخ: المهم الخروج، الذي يخرج منه، أما إذا كان ما خرج منه شيءٌ ما عليه شيء، الدواء طاهر.\nس: هذا المرهم أدخل، قد يكون يدخل ويخرج؟\nالشيخ: إذا أدخله وخرج يُعتبر انتقض.","link":"https://binbaz.org.sa/fatwas/20896/حكم-طهارة-من-يخرج-من-دبره-ساىل-لزج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0691ما حكم وضوء مريض يخرج من دبره سائل لزج في كل وقت؟ ابن باز فتاوى المحاضرات.mp3","categories":["نواقض الوضوء"]},{"id":1029,"question":"ما رأي سماحتكم في أنَّ عمل الطبيب يتطلب في بعض الأحيان رؤية عورة المريض، أو مسّها للفحص؟ وفي بعض الأحيان أثناء العمليات يعمل الطبيبُ الجراح في وسطٍ مليء بالدم والبول، فهل إعادة الوضوء واجبة في هذه الحالات أم أنه لا يجب عليه؟","title":"ما حكم مس الطبيب للعورة والنجاسة للحاجة؟","answer":"الجواب: لا حرج في أن يمسَّ الطبيبُ عورةَ الرجل للحاجة، وينظر إليها للعلاج، سواء كان الدبر أو الذكر، ينظر للحاجة والضَّرورة، ولا بأس أن يلمس الدم إذا دعت الحاجةُ إلى لمسه الجرح لإزالة، أو لمعرفة حال الجرح، ويغسل يده بعد ذلك مما أصابه، ولا ينتقض وضوؤه بلمس الدم والبدن. لكن إذا مسَّ العورة -مس الفرج، مسّ الذكر والدبر- ينتقض وضوؤه، أما إذا مسَّ البدن أو الخصية فقط لا ينتقض وضوؤه، لكن متى مسَّ الذَّكَر من دون حائلٍ –يعني: مسّ اللحمُ اللحمَ- فإنه ينتقض الوضوء؛ لقول النبي ﷺ: مَن أفضى بيده إلى فرجه ليس دونهما سترٌ وجب عليه الوضوء.\nوهكذا الطبيبة إذا مسَّت فرج المرأة للحاجة ينتقض وضوؤها، ولا بأس أن تمسَّ فرج المرأة للحاجة إلى العلاج -الدبر أو القبل للحاجة- وإذا مسَّته من دون حائلٍ بأن مسَّ اللحمُ اللحمَ وهي على وضوء ينتقض الوضوء، لا تُصلي إلا بعد الوضوء؛ لقول النبي ﷺ: مَن أفضى بيده إلى فرجه...، وفي الحديث الآخر: أيُّما رجلٍ أفضى بيده إلى فرجه فعليه الوضوء، وأيما امرأةٍ أفضت بيدها إلى فرجها فعليها الوضوء، وإذا كان فرجُ الإنسان فيه الوضوء، فإذا أفضى إلى فرج غيره من باب أوْلى؛ لأنه أشد عورة، ولكن وجود النَّجاسة لا ينقض الوضوء، كونه يقرب النَّجاسة أو يلمسها بيده للجرح، أو في الفرج، لا ينقض الوضوء، إلا من جهة المس؛ فإذا مسَّ الفرجَ وعلى يده حائل لا ينقض الوضوء، وهكذا الطبيبة إذا كان في يدها حائلٌ عند مسِّ الفرج لا ينتقض الوضوء.","link":"https://binbaz.org.sa/fatwas/21100/ما-حكم-مس-الطبيب-للعورة-والنجاسة-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0896ما حكم مس الطبيب لعورة المريض للحاجة وهل ينتقض وضوءه؟ ابن باز فتاوى المحاضرات.mp3","categories":["نواقض الوضوء","الطب والتداوي"]},{"id":1285,"question":"إذا كنت على طهارةٍ واستلزم الأمرُ الكشف على مريضةٍ، فهل ينقض هذا الوضوء؟","title":"هل ينقض لمسُ المريضة وضوءَ الطبيب؟","answer":"الجواب:\nلا، ما ينقض الوضوء، بعض العلماء يقول: إذا مسَّها بشهوةٍ انتقض وضوؤه، والصواب أنه لا ينتقض الوضوء؛ لأنَّ الرسول ﷺ قبَّل بعض نسائه ثم صلَّى ولم يتوضأ، أما قوله تعالى: أَوْ لَامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به الجماع، وفي قراءةٍ أخرى: أو لمستم، هذا كناية عن الجماع، أما لو قُدِّر أنه لمس بعض جسدها وتلذذ بذلك فلا ينتقض الوضوء، إلا إذا مسَّ الفرج فإنه ينقض الوضوء، إذا مسَّ الفرج -القُبُل أو الدُّبُر- من المرأة أو من نفسه انتقض الوضوء، أما إذا مسَّ غير ذلك: مسّ رأسها أو وجهها أو يدها أو رجلها؛ فإنه لا ينتقض الوضوء بهذا المسِّ، إلا أن يخرج منه شيءٌ، إذا خرج منه مذيٌ انتقض الوضوء، أو مني وجب الغسل.\nأما مجرد المسّ من دون خروج شيءٍ: لا يخرج لا مذي، ولا مني، ولم يمسّ الفرج؛ فهذا لا ينقض الوضوء، لكن عليها الحذر، عليه أن يحذر إذا أحسَّ بهذا، عليه أن يحذر؛ لما يقيه شرّ هذه الفتنة، وليس له أن يخلو بها، بل يجب أن يكون عنده مَن يُشاركه: من امرأةٍ، أو زوجٍ، أو محرمٍ؛ حتى يكون ذلك أبعد للفتنة، وهذا هو الواجب.","link":"https://binbaz.org.sa/fatwas/21350/هل-ينقض-لمس-المريضة-وضوء-الطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1093هل كشف الطبيب على مريضة ينتقض الوضوء؟ ابن باز فتاوى.mp3","categories":["نواقض الوضوء"]},{"id":1842,"question":"الوضوء من مسِّ الذكر يعني لو كان بسرواله سهوًا؟","title":"ما حكم الوضوء من مسِّ الذكر؟","answer":"الجواب:\nمسَّ اللحمُ اللحمَ أم من وراء السِّروال؟\nس: مسَّ اللحمَ بقدرٍ يسيرٍ؟\nج: إن مسَّ اللحمُ اللحمَ يتوضأ، وإن كان من وراء السراويل أو من وراء الثوب أو الإزار فليس فيه شيء، لكن إذا مسَّ اللحمُ اللحمَ -أي مست يدُه فرجَه- فعليه أن يتوضأ، قال النبي: مَن مسَّ ذكرَه فليتوضَّأ.","link":"https://binbaz.org.sa/fatwas/21951/ما-حكم-الوضوء-من-مس-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من مس ذكره فليتوضأ.mp3","categories":["نواقض الوضوء"]},{"id":1928,"question":"إذا مُسَّ (إنسان) من القُبُل أو الدُّبُر يتوضأ صاحبُه؟","title":"حكم وضوء الأم إذا مست فَرْجَ ولدها","answer":"الجواب:\nنعم إذا مسّ فَرْجه، إذا مسَّتْ أمُّه فَرْجَه -قُبُله أو دُبُره- ينقض الوضوء.","link":"https://binbaz.org.sa/fatwas/22041/حكم-وضوء-الام-اذا-مست-فرج-ولدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضوء الأم إذا مست فرج ولدها.mp3","categories":["نواقض الوضوء"]},{"id":2222,"question":"هل خروج الريح أو النوم ينقض الوضوء كاملًا؟","title":"ما حكم الاستنجاء بعد النوم أوخروج الريح؟","answer":"الجواب:\nنعم، لكن ما عليه استنجاء، يبدأ بالمضمضة والاستنشاق، مثل: مسّ الفرج، ويُسميه العامة: التَّمسّح، يعني: الوضوء، فلا يلزمه الاستنجاء إلا من البول والغائط ونحوهما.","link":"https://binbaz.org.sa/fatwas/22345/ما-حكم-الاستنجاء-بعد-النوم-اوخروج-الريح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خروج الريح أو النوم للمتوضئ.mp3","categories":["نواقض الوضوء"]},{"id":2765,"question":"إذا توضأ إنسان ثم بعد ذلك قَلَّم أظفاره ؟","title":"حكم مَنْ توضأ ثم قَلَّم أظفاره","answer":"الجواب: ما يضر، ما يضر.","link":"https://binbaz.org.sa/fatwas/22913/حكم-من-توضا-ثم-قلم-اظفاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من توضأ ثم قلم أظفاره.mp3","categories":["نواقض الوضوء"]},{"id":3015,"question":"خروج الدم هل ثبت فيه دليل أنه ناقض للوضوء؟","title":"هل خروج الدم ينقض الوضوء؟","answer":"الجواب: ما أعلم فيه شيئًا واضحًا، إلا إذا كان مِن الفَرْج كالمستحاضة، أما إذا كان من غير الفَرْج فالأحوط فيه الوضوء إذا كَثُر، والقليل يُعفى عنه، لكن إذا كثر فالأحوط فيه الوضوء خروجًا من الخلاف.","link":"https://binbaz.org.sa/fatwas/23173/هل-خروج-الدم-ينقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خروج الدم هل ينقض الوضوء.mp3","categories":["نواقض الوضوء"]},{"id":3565,"question":"كون النبي ﷺ صلّى بعد النوم؟","title":"كيف كانت صلاة النبي ﷺ بعد نومه؟","answer":"الجواب: لأن نومه لا ينقض عليه الصلاة والسلام (تنام عيناه ولا ينام قلبه) عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23747/كيف-كانت-صلاة-النبي-ﷺ-بعد-نومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة النبي بعد نومه.mp3","categories":["نواقض الوضوء"]},{"id":4454,"question":"الذي يأخذ ماءً جديدًا للمعة أو يدلك به بقية..؟","title":"كيفية غسل اللمعة عند الوضوء","answer":"الجواب: إذا كان الوضوء ما بعد طال الفصل يكفي غسل اللمعة، إلا إذا كان في الذراع يغسل ما بعدها أيضًا، يُعيد ما بعدها حتى يحصل الترتيب.\nس: إذا كانت ..؟\nج: إذا كانت اللمعة يغسلها وما بعدها: كمسح وغسل الرِّجلين حتى يحصل الترتيب، وأما إذا كانت اللمعة في الرِّجْل يكفي.... ولا حاجة إلى شيءٍ آخر.\nس: بعض الناس إذا رأى اللمعة في الصلاة يبلها بريقه ويكتفي بهذا؟\nج: لا.... هذا غلط، النبي قال له يُعيد ﷺ.","link":"https://binbaz.org.sa/fatwas/24732/كيفية-غسل-اللمعة-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/غسل اللمعة عند الوضوء.mp3","categories":["نواقض الوضوء"]},{"id":4466,"question":"إذا كان الولد صغيرًا، عمره مثلًا سنة، وأمه مثلًا... عنده؟","title":"حكم طهارة الأم إذا مسّت فرج ولدها الصغير","answer":"الجواب: تتوضأ إذا مسته، تتوضأ لأن في الحديث: مَن مسَّ الذكر...\nس: ولو صغيرًا؟\nج: ولو صغيرًا نعم.","link":"https://binbaz.org.sa/fatwas/24744/حكم-طهارة-الام-اذا-مست-فرج-ولدها-الصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتوضأ الأم إذا مست فرج ولدها الصغير.mp3","categories":["نواقض الوضوء","قضايا المرأة"]},{"id":4750,"question":"إذا كان يرى نقضَ الوضوء بأكل لحم الجزور، والإمام لا يرى نقضه؟","title":"حكم إمامة من لا يرى نقضَ الوضوء بأكل لحم الجزور","answer":"تُصلي خلفه، هذا محل اجتهادٍ.  لكن لو علم أنه أظهر ما يُوجب الوضوء: من صوتٍ، أو ريحٍ، ومع ذلك يُصلي بالناس، فلا، أما الذي محل اجتهادٍ: كمس المرأة، ومثل: أكل لحم الإبل، لا يراه ناقضًا؛ يُصلي خلفه.","link":"https://binbaz.org.sa/fatwas/25091/حكم-امامة-من-لا-يرى-نقض-الوضوء-باكل-لحم-الجزور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة وراء من لا يرى نقضَ الوضوء بأكل لحم الجزور.mp3","categories":["نواقض الوضوء"]},{"id":5311,"question":"رجل أكل لحم بعير ولم يتوضأ مع علمه بالحكم وتوفر الماء، فهل تبطل صلاته؟","title":"ما حكم صلاة من لم يتوضأ من لحم البعير؟","answer":"الجواب: نعم، النبي ﷺ أمر بالوضوء من لحوم الإبل، وقال: توضؤوا من لحوم الإبل ولا توضؤوا من لحوم الغنم وقد سئل، يا رسول الله، أنتوضأ من لحوم الإبل؟ قال: نعم، فالذي يصلي وقد أكل لحم الإبل يعيد الصلاة إذا كان ما توضأ، هذا هو المشروع.[1]","link":"https://binbaz.org.sa/fatwas/30969/ما-حكم-صلاة-من-لم-يتوضا-من-لحم-البعير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 031.mp3","categories":["نواقض الوضوء"]},{"id":5563,"question":"بعض النساء تستخدم بعض الأصباغ التي تمنع وصول الماء إلى البشرة؟","title":"ما حكم الصلاة مع أصباغ تمنع الوضوء جهلًأ؟","answer":"الجواب: إذا كان فيه شيء يمنع يُزال، كل شيء يمنع وصول الماء يزال في الوضوء والغسل: عجين أو أصباغ أو مناكير، العامَّة يُسمونها: مناكير، لا بدَّ من إزالتها حتى يصل الماء إلى البشرة. س: لكن إذا صلَّت وهي جاهلة بالحكم، صلَّت فترةً طويلةً؟ ج: الطويلة عفا الله عمَّا مضى، أما إن كان شيئًا قليلًا -فرضًا أو فرضين- تُعيد، تُعلم بالإعادة، النبي ﷺ سكت عن كثيرٍ من المستحاضات، ما أمرهن بالإعادة، وقد مضى عليهن دهر، والأعرابي الذي نقر صلاته أمره أن يُعيد الصلاة الحاضرة، ولم يأمره بالماضي؛ لأنَّ هذا قد يطول وقد يكثر. س: المرأة التي صلت وهي جاهلة، هل يُعفى عنها أو الكثير؟ ج: إذا كان فرضًا أو فرضين تُعيد من باب التَّحذير، ومن باب الحثِّ على الاستقامة، أما الشيء الذي مضت عليه شهور أو سنين هذا صعب، الرسول ﷺ لما علَّم الأعرابي أمره أن يُعيد الحاضرة، ولم يقل له: أعد صلواتك الماضية، والمستحاضات اللاتي تركن الصلاة دهرًا علَّمهن، ولم يقل لهن: أعدن ما مضى.[1]","link":"https://binbaz.org.sa/fatwas/31515/ما-حكم-الصلاة-مع-اصباغ-تمنع-الوضوء-جهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 003.mp3","categories":["نواقض الوضوء"]},{"id":5565,"question":"إذا رأى لمعةً في الكعب وهو في الصلاة، هل له أن يخرج عن صلاته ويُعيد الوضوء؟","title":"ماذا يفعل من رأى لمعة في عقبه لم يصلها الماء؟","answer":"الجواب: نعم، إذا رأى لمعةً فوضوؤه باطل، وقد زالت الموالاة، انتهى، يُعيد الوضوء. س: وإن رآها بعد أن فرغ من صلاته؟ ج: يُعيد الوضوء والصلاة.[1]","link":"https://binbaz.org.sa/fatwas/31517/ماذا-يفعل-من-راى-لمعة-في-عقبه-لم-يصلها-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 005.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":5570,"question":"الرّطوبات التي تخرج من فرج المرأة؟","title":"حكم الرّطوبات التي تخرج من فرج المرأة؟","answer":"الجواب: تنقض الوضوء نعم؛ لأنها خارج من السَّبيلين.[1]","link":"https://binbaz.org.sa/fatwas/31522/حكم-الرطوبات-التي-تخرج-من-فرج-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 010.mp3","categories":["نواقض الوضوء"]},{"id":5571,"question":"الدليل على أنَّ الخارج من غير السبيلين ينقض؟","title":"هل ينتقض الوضوء من القيء؟","answer":"الجواب: حديث: \"قاء فتوضَّأ\"، والقياس عليه من جهة الفحش والخبث، والأصل في هذا: قاء فتوضأ، لا أعلم –يعني- شيئًا واضحًا في الموضوع سوى أنه قاء فتوضأ، والقياس على ما يخرج من السبيلين؛ لأنه قد أشبه ما خرج من السبيلين من بولٍ أو مذي أو نحو ذلك. وبعض أهل العلم ما يرى النقض في الخارج من غير السبيلين. هذا من باب الاحتياط، الخارج من غير السبيلين من باب الاحتياط والخروج من الخلاف. س: حديث الترمذي ثابت؟ ج: \"قاء فتوضأ\"، وفي بعض الروايات: \"قاء فأفطر\"، وفي سنده مقال، وفي متنه اختلاف أيضًا.[1]","link":"https://binbaz.org.sa/fatwas/31523/هل-ينتقض-الوضوء-من-القيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 011.mp3","categories":["نواقض الوضوء"]},{"id":5696,"question":"متوضئ حك يده، أو رجله، وسها حتى خرج الدم، فهل يفسد الوضوء؟","title":"من خرج منه دم وهو على طهارة","answer":"الجواب: لا يضر، هذه مسائل طفيفة، إذا حك رجله، أو كذا، أو ضربه شيء بأصبعه، أو برجله، وخرج الدم لا ينقض الوضوء، إنما الخلاف في الوضوء في الدم الكثير إذا وقع، هل ينقض، أو لا ينقض؟  أما الشيء اليسير، الرعاف اليسير ، جرح يسير في رجله، في يده هذا ليس فيه خلاف أنه لا ينقض الوضوء، ولا يضره.","link":"https://binbaz.org.sa/fatwas/985/من-خرج-منه-دم-وهو-على-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_14.mp3","categories":["نواقض الوضوء"," الوسواس بأنواعه"]},{"id":6054,"question":"ما الحكم في المرأة إذا لمست زوجها، هل يجب عليه الوضوء، أم لا؟","title":"حكم ملامسة المتوضئ لزوجته","answer":"الجواب: لمس المرأة للزوج، ولمس الرجل للمرأة لا ينقض الوضوء على الصحيح إذا كان ما خرج شيء، فلمسها له، ولمسه لها لا ينقض الوضوء على الصحيح. بعض أهل العلم يرى أن لمس المرأة مطلقًا ينقض الوضوء، وبعضهم يقول: إذا لمسها بشهوة بتلذذ؛ ينتقض وضوؤه، والصواب: القول الثالث، وأنه لا ينقض الوضوء مطلقًا إذا كان ما خرج شيء ملامسته لها، وملامستها له، والصواب: أنه لا ينقض الوضوء. وأما قوله -جل وعلا-: أَوْ لَامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به: الجماع، كما قاله ابن عباس وجماعة. وقد ثبت أنه ﷺ قبل بعض نسائه، ثم صلى، ولم يتوضأ، وهذا مسيس، والمقصود أن الملامسة التي في القرآن العظيم أَوْ لَامَسْتُمُ [النساء:43] وفي قراءة أو لمستم معناها: الجماع عند جمع من أهل العلم، وهو الصواب، وهو قول ابن عباس، وجماعة، رحمة الله عليهم.","link":"https://binbaz.org.sa/fatwas/1449/حكم-ملامسة-المتوضى-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_377.mp3","categories":["نواقض الوضوء","قضايا المرأة"]},{"id":6292,"question":"رجل عنده سلس في البول يقول: إذا دخل الوقت وتوضأ فبعد الوضوء يخرج ما لا يزيد نقطتين من البول، وهو متحرج من ذلك؟","title":"حكم وضوء من به سلس في البول","answer":"الجواب: إذا خرج شيء يعيد الاستنجاء، ويعيد الوضوء، ويترك الوساوس، لا يعجل حتى يستنجي، ثم إذا استنجى؛ قام، وتوضأ، وترك الوساوس، ويغسل ما حول فرجه بالماء بعد الوضوء؛ حتى يحمل ما يقع من الوسوسة على هذا الرش، وبعد ذلك ينتهي هذا الشيء، ويذهب عنه هذا الشيء. لكن لو أنه خرج منه شيء بعد ذلك؛ يعيد الاستنجاء، ويعيد الوضوء، ويغسل ما أصاب ثوبه، أو سراويله بعد ذلك، ثم يترك الوساوس، ويقطعها، ويشتغل بنفسه، ويعرض عن هذه الوساوس؛ حتى لا يستثيره الشيطان، وحتى لا يتلاعب به الشيطان، رزق الله الجميع التوفيق، والهداية.","link":"https://binbaz.org.sa/fatwas/1807/حكم-وضوء-من-به-سلس-في-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_648.mp3","categories":["نواقض الوضوء","قضاء الحاجة"," الوسواس بأنواعه"]},{"id":6391,"question":"من توضأ، ومسح على الجورب، ثم بعد انتهائه من الوضوء بفترة خلع الجورب، فهل يبطل الوضوء بخلعه للجورب، أم لا؟","title":"حكم خلع الجورب لمن هو على طهارة","answer":"الجواب: إذا مسح الجورب بعد الحدث، ثم خلعه؛ بطل الوضوء عند عامة أهل العلم.  فيه قول شاذ لبعض التابعين، لكن ليس  عليه المعول. الذي عليه عامة أهل العلم أنه يبطل الوضوء إذا خلع الخفين، والجوربين بعد المسح، وقد أحدث قبل ذلك، يبطل الوضوء، نعم. السؤال: يعني لا يكتفي بغسل الرجل فقط؟ الجواب: لا، يعيد الوضوء، الوضوء كله من أوله.","link":"https://binbaz.org.sa/fatwas/1973/حكم-خلع-الجورب-لمن-هو-على-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_760.mp3","categories":["نواقض الوضوء","قضايا المرأة"]},{"id":7619,"question":"هذه الرسالة من علي سالم مؤمن ، يقول في رسالته: ببالغ الفرح والسرور أكتب هذه الرسالة، وأقدم الشكر والامتنان لكل من يساهم في إنجاح هذا البرنامج، وأرجو من فضيلة الشيخ عبد العزيز بن عبد الله بن باز الرد على سؤالي هذا، يقول: إذا حصل أن لمست يدي يد زوجتي عفواً أو العكس، فهل ينقض الوضوء أم لا؟","title":"حكم نقض الوضوء من لمس الزوجة","answer":"الجواب: مس المرأة سواءً كان ذلك عمداً أو من غير عمد، لا ينقض الوضوء على الصحيح، وقد اختلف العلماء في ذلك، فقال بعضهم: إن مسها ينقض مطلقاً، وقال بعضهم: لا ينقض مطلقاً، وقال بعض أهل العلم: ينقض مع الشهوة، وهي: التلذذ بمسها، ولا ينقض المس بدون ذلك، والصواب قول من قال: إنه لا ينقض مطلقاً؛ لأنه ثبت عن رسول الله ﷺ: أنه قبل بعض نسائه ثم صلى ولم يتوضأ ولأن الأصل سلامة الطهارة، وعدم انتقاضها إلا بدليل، وليس هناك دليل واضح ثابت يدل على انتقاضها بمس المرأة، فوجب حينئذٍ أن تبقى الطهارة على حالها وألا تنتقض بالمس لعدم الدليل على ذلك، بل لوجود الدليل على أن مسها لا ينقض ولو كان بشهوة؛ لأن القبلة في الغالب لا تكون إلا عن شهوة عن تلذذ، فالحاصل أن الصواب والراجح من أقوال العلماء أن مس المرأة بشهوة أو بغير شهوة لا ينقض الوضوء، سواءً كان زوجته أو غير زوجته، هذا هو الصواب، وأما قوله جل وعلا: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] وفي قراءة: أو لمستم النساء المراد بذلك على الصحيح الجماع، هذا قول ابن عباس وجماعة من أهل العلم وهو الصواب، أما قول من قال: إن المراد به مس المرأة، كما هو عن ابن مسعود ، يعني: مسها باليد، فهذا مرجوح، والله جل وعلا يعبر عن الجماع بالمسيس واللمس والمباشرة كما في قوله جل وعلا: وَلا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ [البقرة:187] وقال هنا: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به هنا الجماع، وهكذا قراءة من قرأ: أو لمستم منْ قَبْلِ أَنْ تَمَسُّوهُنَّ [الأحزاب:49] في طلاق غير المدخول بها، فالمراد بكله الجماع، هذا هو الصواب وهو الحق إن شاء الله . نعم. \nالمقدم: لكن سماحة الشيخ هناك من يقول: إن مثلاً تقبيل الرسول ﷺ لا يقاس عليه؛ لأن الرسول ﷺ يستطيع أن يمسك نفسه وألا يقع فيما يقع فيه العامة الآن؟ \nالشيخ: ليس بشيء، هذا القول ليس بشيء، هو المشرع لنا، هو القدوة عليه الصلاة والسلام، ولما قيل له في مثل هذا قال: إني أخشاكم لله وأتقاكم له عليه الصلاة والسلام، لما سأله سائل قال له: يا رسول الله! قد غفر الله لك، في مسائل عديدة، قال: إني أخشاكم لله وأتقاكم له عليه الصلاة والسلام، فالحاصل أنه القدوة والأسوة في كل شيء عليه الصلاة والسلام إلا ما دل ما قام الدليل على أنه خاص به عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/4672/حكم-نقض-الوضوء-من-لمس-الزوجة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02402.mp3","categories":["نواقض الوضوء"]},{"id":7754,"question":"هذه رسالة من المرسل من الرس (م. م. م) يقول في رسالته: ما حكم من شك في انتقاض الوضوء؛ فهل يتوضأ أم لا؟ أثابكم الله.","title":"حكم الشك في انتقاض الوضوء","answer":"الجواب: إذا شك الإنسان أن انتقض وضوءه ليس عليه الوضوء، إذا كان قد عرف الطهارة قد توضأ فعرف أنه متطهر للظهر مثلاً ثم شك بعد ذلك هل انتقضت طهارته أم لا؟ ليس عليه وضوء، بل يصلي العصر بالطهرة الأولى، وهكذا أشباه ذلك، توضأ الضحى يصلي الضحى، ثم شك هل انتقضت طهارته؛ لا يتوضأ لا يلزمه الوضوء للظهر بل يصلي بطهارته التي أتى بها ضحىً، وهكذا في الليل مثلاً تهجد فلما جاء الفجر شك هل أحدث أم لا؟! لا حرج عليه ولا وضوء عليه بل يصلي بوضوئه السابق الذي أتى به في أثناء الليل، ولا يحتاج إلى وضوء لقول النبي ﷺ لما سئل عن الرجل يجد الشيء في الصلاة قال: لا ينصرف حتى يسمع صوتاً أو يجد ريحاً متفق عليه، وفي لفظ آخر لما سئل قالوا:- يا رسول الله، رجل يجد الشيء في بطنه قال: لا يخرج من المسجد حتى يسمع صوتاً أو يجد ريحاً فالحاصل أنه ليس عليه أن يجدد وضوءه حتى يتحقق ويعلم أنه أحدث من ريح أو بول أو غائط أو أكل لحم إبل أو ما أشبه من النواقض، الحاصل أنه لا يلزمه الوضوء إلا إذا تحقق وجود الناقض، كما قاله النبي ﷺ: فلا ينصرف حتى يسمع صوتاً أو يجد ريحاً، يعني: حتى يتحقق الحدث، فإذا لم يتحقق فالأصل الطهارة وله ثلاث حالات:\nحالة يتحقق أنه أحدث؛ فعليه الوضوء.\nحالة يتحقق أنه لم يحدث؛ فالحمد لله هذا يصلي بوضوئه الأول.\nالحالة الثالثة: شك تردد: هل أحدث أم لا؟ وقد يغلب على ظنه الحدث، وقد يغلب على ظنه عدم الحدث، وقد يستوي الطرفان؛ ففي هذه الأحوال الثلاثة لا يلزمه الوضوء حتى يتيقن أنه أحدث. نعم.\nالمقدم: لكن أيهما أفضل إذا جمع أكثر من صلاة في وضوء واحد أو توضأ لكل صلاة مكتوبة؟\nالشيخ: إذا توضأ لكل صلاة أفضل؛ لما في الوضوء من الخير والفائدة، الوضوء فيه فضل عظيم، فإذا توضأ لكل صلاة فهذا فيه فضل عظيم، وإن صلى بوضوء واحد عدة صلوات؛ فلا بأس قد فعله النبي صلى الله عليه وسلم في بعض الأحيان، كما يصلي الإنسان المجموعة الظهر والعصر بوضوء واحد في السفر والمغرب والعشاء بوضوء واحد في السفر أو في المرض. نعم.","link":"https://binbaz.org.sa/fatwas/4951/حكم-الشك-في-انتقاض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_043/04303.mp3","categories":["نواقض الوضوء"]},{"id":7758,"question":"سؤال محفوظ محمد البكري من جمهورية اليمن الديمقراطية الأخير يقول: أحسن رجل الوضوء مقلداً الإمام الشافعي رحمه الله، ثم مس امرأة أجنبية وقال: قلدت الإمام مالك وصلى، هل صلاته صحيحة بهذا الخلط بين المذهبين أم لا؟","title":"حكم صلاة من مس امرأة أجنبية","answer":"الجواب: ينبغي للمؤمن ألا يكون عمله هكذا بالتقليد، بل ينبغي له أن يسأل أهل العلم أو يتفقه إن كان عنده فقه، وينظر في الأدلة الشرعية حتى يأخذ بالدليل لا بالآراء المجردة، فيتابع هواه في مسألة ويتابع هواه في مسألة أخرى، فيقلد هذا تارة وهذا تارة، هذا ليس من شأن أهل العلم، وليس من شأن أهل الورع والاجتهاد في الدين، فالواجب على طالب العلم أن يعتني بالأدلة وأن يأخذ بما يقوم عليه الدليل فإن كان قاصراً عن ذلك نظر في كلام أهل العلم، وأخذ بما يراه أقرب إلى الصواب من أقوالهم، وتحرى الحق في ذلك، والصواب في هذه المسألة أن مس المرأة لا ينقض الوضوء، هذا هو الصواب؛ لأن النبي صلى الله عليه وسلم كان ربما قبل بعض نسائه ثم صلى ولم يتوضأ؛ ولأن الأصل صحة الطهارة وسلامتها، فلا يجوز أن يقال بفسادها إلا بدليل، وليس هناك دليل واضح مع من قال بأن مس المرأة ينقض الوضوء مطلقاً سواء بشهوة أو بغير شهوة، هذا هو الصواب وهذا هو الأرجح من حيث الأدلة، والعلماء لهم ثلاثة أقوال في هذا:\nمنهم من قال: إن مسها ينقض مطلقاً.\nومنهم من قال: لا ينقض مطلقاً.\nومنهم من قال: ينقض بشهوة، ولا ينقض إذا كان بغير شهوة.\nوالقول الأرجح قول من قال: إنه لا ينقض مطلقاً؛ لعدم الدليل على النقض، أما قوله جل وعلا: أَوْ لَامَسْتُمُ النِّسَاءَ [النساء:43] وفي قراءة أو لمستم النساء فقد فسر ذلك ابن عباس بأنه الجماع، وهو الصواب، المراد به الجماع، ليس المراد به الجس باليد، المراد به الجماع، فقوله: أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ [المائدة:6] هذا إشارة إلى الحدث الأصغر، أَوْ لَامَسْتُمُ النِّسَاءَ إشارة إلى الحدث الأكبر وهو الجنابة، فأشار إلى هذا بما يناسبه وهو الملامسة، وأشار إلى الحدث الأصغر: أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ .\nفالحاصل أن الصواب في هذه المسألة هو مع من قال: إن مس المرأة لا ينقض الوضوء مطلقاً. نعم.\nوالنبي ﷺ -مثلما تقدم- قبل بعض نسائه ثم صلى ولم يتوضأ، اللهم صل عليه وسلم. نعم.","link":"https://binbaz.org.sa/fatwas/4963/حكم-صلاة-من-مس-امراة-اجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_044/04407.mp3","categories":["نواقض الوضوء"]},{"id":7879,"question":"الرسالة التي بين يدينا والأخيرة في لقائنا هذا وردتنا من بلاد زهران من عبد الوهاب مسفر زهراني يقول: السلام عليكم ورحمة الله وبركاته، وبعد:أرجو توضيح هذه الأسئلة: ما حكم من غسل ميتاً أيجب عليه الغسل أم الوضوء أم غير ذلك؟","title":"حكم الغسل لمن غسل ميتاً","answer":"الجواب: من غسل ميتاً فينبغي له أن يتوضأ؛ لأنه أفتى بهذا جماعة من الصحابة ينبغي له أن يتوضأ وضوء الصلاة التمسح يعني، يعني: يتمضمض ويستنشق، يغسل وجهه وذراعيه ويمسح رأسه وأذنيه ويغسل قدميه، هذا هو الوضوء الشرعي، ينبغي أن يتوضأ خروج من خلاف العلماء، وعملاً بما أفتى به بعض الصحابة رضي الله عنهم وأرضاهم.\nأما الغسل فلا يجب عليه لكن إذا اغتسل هو أفضل، الغسل -التروش- أفضل ولا يجب، وجاء في الحديث الصحيح عنه ﷺ أنه كان يغتسل من غسل الميت، فإذا غسل ميتاً شرع له يغتسل -يتروش-.\nوأما الوضوء فيجب وجوب عند جمع من أهل العلم، وإذا مس فرجه وجب الوضوء بكل حال، لكن المشروع للذي يغسل الميت أنه لا يمس الفرج بل يغسله من وراء خرقة، يغسل فرجه بخرقة لا يلمس الفرج، لكن لو قدر أنه لمسه جهلاً أو خطأ فإنه ينتقض الوضوء بكل حال، لكن لو غسله بخرقة ولم يمس الفرج لا الدبر ولا القبل فإنه ينبغي له أن يتوضأ وضوء الصلاة فقط، هذا يجب عند جمع من أهل العلم، وأما الغسل فلا يجب قولاً واحداً، بل يستحب استحباباً ويشرع ذلك.\nقال بعض أهل العلم: ولعل العلة في ذلك والحكمة في ذلك أن تقليب الميت مما يوهن القوى ويضعف القوى؛ لأنه سيتذكر الموت ويتذكر حال القبر فيحصل له ضعف في قواه وانهيار، فشرع الله الغسل حتى يستفيد من ذلك وحتى يقوى وينشط بعد الضعف الذي أصابه.\nالمقدم: يقول في سؤاله الثاني: ما الحكم في قول: وجه الله عليك! تفضل معنا، أو وجه الله عليك! اعمل هذا الشيء، أو جاه الله عليك! أو أن عليك وجه الله! ونفيدكم أنها عادة منتشرة في الجنوب من المملكة أفيدونا وفقكم الله؟\nالشيخ: لا أدري، في الوقت الحاضر لا أدري وسوف أدرسها إن شاء الله، فأما الآن فلا أدري، لكن سوف أدرسها وأنظر فيها وتكون في وقت آخر إن شاء الله. يكون الجواب عنها في وقت آخر وأنت يا أخ سليمان تذكرني بها إن شاء الله.\nالمقدم: إن شاء الله.\nالشيخ: حتى أعيد البحث.. حتى أعيد النظر فيها.\nالمقدم: إن شاء الله تعالى.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/5347/حكم-الغسل-لمن-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_057/05705.mp3","categories":["نواقض الوضوء"]},{"id":7929,"question":"هذه الرسالة وردت للبرنامج من عواد عقلة غضيان من الأردن الرصيفة يقول فيها: السلام عليكم ورحمة الله، بعد الإعجاب والإكبار لبرنامجكم في إذاعة المملكة العربية السعودية الذي أستمع إليه عبر الأثير باستمرار بانتظام، أريد أن أعرض عليكم مسألة وأرجو أن تفيدوني بإجابة وافية وشافية هي حول لمس النساء، هل ينقض الوضوء أم لا؟ وأرجو عرض هذه المسألة على أحد الشيوخ العلماء عندكم وفقكم الله؟","title":"حكم لمس المرأة بعد الوضوء","answer":"الجواب: لا شك أن لمس النساء اختلف فيه العلماء، فقال قوم من أهل العلم: إن لمس المرأة من دون ساتر من دون حجاب ينقض الوضوء مطلقاً، وهو مشهور مذهب الشافعي رحمه الله وجماعة، وقال آخرون: لا ينقضه مطلقاً، وإنما المراد باللمس: الجماع في قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43]، قالوا: المراد هنا: الجماع كما قال ابن عباس وجماعة، وقال آخرون: ينقض إن كان بشهوة، ولا ينقض إذا كان بغير شهوة، وهو مشهور مذهب أحمد رحمه الله وجماعة.\nوالأرجح عندي بعد التأمل هو قول من قال: إنه لا ينقض مطلقاً، وأن مسها لا ينقض مطلقاً وإنما الذي ينقض مس الفرج، أما مس المرأة فقط في يدها أو رجلها فلا ينقض الوضوء لعدم الدليل، أما قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به الجماع كما تقدم؛ لقول ابن عباس رحمة الله عليه وجماعة من أهل العلم، أما قول ابن مسعود المراد به: المس فقط فليس بظاهر، بل الصواب ما قاله ابن عباس في هذا، وأن المراد به الجماع خاصة، والدليل على هذا: أنه ثبت عنه ﷺ أنه قبل بعض نسائه ثم صلى ولم يتوضأ، ثم أمر آخر وهو أن اللمس أمر واقع من الناس في بيوتهم، والحاجة ماسة إلى بيانه من النبي ﷺ بياناً شافياً عاماً حتى يعلمه الناس، فلو كان ينقض الوضوء لبينه النبي ﷺبياناً واضحاً كافياً شافياً، ولم يرد عنه ﷺ ما يدل على أنه ينقض الوضوء، فعلمنا بذلك أن مس المرأة لا ينقض الوضوء مطلقاً، سواء كان عن تلذذ وشهوة أم لم يكن كذلك، بل الذي ينقض هو الجماع، وكذلك مس الفرج، هذا هو الذي ينقض، أما مجرد لمس المرأة فقط من غير خروج شيء فإنه لا ينقض، أما إن خرج منه شيء كالمذي فإنه ينتقض الوضوء، إذا مسها بشهوة وخرج المذي انتقض الوضوء وعليه حينئذ أن يغسل فرجه من المذي، يغسل فرجه وأنثييه ويتوضأ للصلاة ونحوها، أما مس بدون خروج شيء، مسها ولم يخرج منه شيء فإنه لا ينقض الوضوء على الصحيح، والدليل ما تقدم، الدليل: أن النبي ﷺ قبل بعض نسائه ثم صلى ولم يتوضأ وهذا ثابت عنه بإسناد جيد رواه أحمد وغيره، وله شاهد مرسل عند النسائي ، ثم الأصل عدم النقض، هذا هو الأصل، فمن قال بالنقض مطلقاً فعليه الدليل، وهكذا من قال بالنقض بالشهوة عليه الدليل ولا دليل، فالصواب أنه لا ينقض الوضوء، وكثير من إخواننا في الطواف يتحرجون إذا مست يده يد امرأة أو رجله رجل امرأة راح يتوضأ أخذاً بقول من قال: إنه ينقض مطلقاً، وهذا فيه حرج كثير بدون دليل ولا حجة، والصواب إن شاء الله: أنه لا ينقض الوضوء مطلقاً، هذا هو الصواب.\nالمقدم: شكراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/5440/حكم-لمس-المراة-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_065/06504.mp3","categories":["نواقض الوضوء"]},{"id":7987,"question":"هذه الرسالة وردتنا من القصيم من بريدة المرسل صالح حمود الحربي ، يقول في رسالته: بسم الله الرحمن الرحيم، أصحاب الفضيلة، السلام عليكم ورحمة الله وبركاته وبعد:ما هو الدليل الذي استند عليه الإمام أحمد رحمه الله بإلزام آكل لحم الجزور بالوضوء، وكذلك الدليل باستثناء الأجزاء التي لا تنقض الوضوء من لحم الجزور؟","title":"الأدلة على وجوب الوضوء من لحم الجزور","answer":"الجواب: هذه المسألة ليست خاصة بأحمد، بل قاله أحمد وجماعة كبيرة من أهل الحديث، وحجتهم ما ثبت عن رسول الله عليه الصلاة والسلام من حديث جابر بن سمرة أنه سئل عليه الصلاة والسلام قيل: يا رسول الله ! أنتوضأ من لحوم الإبل؟ قال: نعم، فقيل له: أنتوضأ من لحوم الغنم؟ قال: إن شئت فخير في لحوم الغنم ولم يخير في لحوم الإبل بل أوجب ذلك.\nوحديث البراء بن عازب أيضاً وهو حديث صحيح أن النبي عليه السلام قال: توضئوا من لحوم الإبل ولا توضئوا من لحوم الغنم فأمر بالوضوء من لحوم الإبل دون غيرها، فهذا هو الحجة لـأحمد ولغيره من أئمة الحديث الذين قالوا بهذا، وقولهم هو الصواب، والذين خالفوهم احتجوا بحديث لا حجة فيه، وهو حديث جابر أنه قال: كان آخر الأمرين من رسول الله ترك الوضوء مما مست النار فقوله: كان آخر الأمرين من النبي ﷺ ترك الوضوء مما مست النار لا حجة فيه؛ لأن هذا عام ومفسر، مفسر بأنه أكل لحم غنم فتوضأ.. ثم صلى، ثم أكل من بقية اللحم ثم صلى الصلاة الثانية ولم يتوضأ.\nوقد جاء عنه في عدة أحاديث أنه أكل من لحم الغنم ولم يتوضأ، فدل ذلك على أن ما مست النار نسخ الوضوء منه؛ لأنها جاءت أحاديث كثيرة عنه عليه الصلاة والسلام أنه أكل مما مست النار ثم صلى ولم يتوضأ، فدل ذلك على أن الأمر بالوضوء مما مست النار قد نسخ، وقال قوم: إنه لم ينسخ ولكنه بقي للندب فقط، ولكن الأظهر النسخ؛ لأنه قال في حديث البراء: توضئوا من لحوم الإبل ولا توضئوا من لحوم الغنم فدل على أنه غير مشروع ولا مستحب قال: لا توضئوا من لحوم الغنم وقوله في لحوم الغنم: إن شئت فدل ذلك على أنه لا يجب ولا يشرع، وإنما الواجب الوضوء من لحم الإبل خاصة، وأما الوضوء مما مسته النار مثلما قال جابر نسخ: وكان آخر الأمرين من النبي ﷺ ترك الوضوء مما مست النار هذا هو القول الفصل في هذه المسألة. نعم.","link":"https://binbaz.org.sa/fatwas/5542/الادلة-على-وجوب-الوضوء-من-لحم-الجزور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07303.mp3","categories":["نواقض الوضوء"]},{"id":7989,"question":"أيضاً بالنسبة للحم الجزور له سؤال آخر يقول: هل الذين لا يتوضئون من لحم الجزور صلاتهم باطلة أم لا، نريد الإفادة أفادكم الله؟","title":"بعض أجزاء الجزور التي لا تنقض الوضوء","answer":"الجواب: كذلك سبق أنه سأل عن الأجزاء الأخرى التي لا تنقض من الجزور كالكرش والأمعاء وأشباه ذلك، فمشهور في مذهب أحمد وجماعة أنه لا يتوضأ منها، إنما يتوضأ من اللحم؛ لأن الرسول ﷺ قال: توضئوا من لحوم الإبل والكرش ما تسمى لحم عند العرب، ولا يسمى الأمعاء لحم، والكبد والطحال وأشباه ذلك، وإنما اللحوم المعروفة، الهبر المعروف، فلهذا قال أهل العلم: إنه يتوضأ من الهبر من اللحم، ولا يتوضأ من كرش وأمعاء ونحو ذلك، هذا هو المشهور عند أهل العلم القائلين بنقض الوضوء من لحم الإبل.\nوقال جماعة: يلحق بذلك الكرش ونحوه وأنها كلها تلتحق باللحم؛ لأن الله لما حرم الخنزير حرم لحمه وشحمه وكل شيء، قالوا: فهذا يلحق باللحم، والقول الأول أظهر من جهة تعليق الحكم باللحم، ... توضئوا من لحوم الإبل، أما الخنزير فقد حرمه الله كله، فلا ينظر في أمره بل كله حرام، أما هذا شيء يتعلق بالعبادات، واللحم وتوابعه ليس بنجس، بل لحمه أباحه الله، فإن لحم الإبل مباح لنا، لكن الله علق باللحم منه الوضوء دون البقية فلا بأس أن يستثنى منه ما لا يسمى لحماً عند العرب.\nوإذا توضأ الإنسان من بقية الإبل من الكرش ....... والأمعاء مثل الأذن مثل اللسان، إذا توضأ منها فهو حسن من باب الاحتياط، من باب الخروج من الخلاف ومن باب الأخذ بالحيطة؛ لأن هذه تابعة للحوم وليست لحوم تابعة، هذا من باب الاحتياط حسن، أما الوضوء الذي يلزم بلا شك فهو إذا أكل من اللحم.","link":"https://binbaz.org.sa/fatwas/5545/بعض-اجزاء-الجزور-التي-لا-تنقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07305.mp3","categories":["نواقض الوضوء"]},{"id":7990,"question":"المقدم: السؤال الآخر يقول: هل الذين لا يتوضئون من لحم الجزور صلاتهم باطلة أم لا، نرجو الإفادة؟","title":"حكم من صلى دون أن يتوضأ من لحم الجزور","answer":"الجواب: نعم، إذا كان لا يعتقد أن لحم الإبل لا ينقض بل يعتقد أنه ينقض ثم تساهل تبطل صلاته، أما إنسان يعتقد أنه لا ينقض، ويرى أن لحم الإبل منسوخ، وأنه تبع المنسوخات، ويعتقد هذا، أو قلد من قال ذلك باجتهاده وأن هذا هو الأصوب عن تقليد أو عن اجتهاد، وهذا الذي في نفسه، اعتقاده أن هذا هو الأولى، صلاته غير باطلة صلاته صحيحة، حسب اعتقاده، مثل طالب علم اجتهد ورأى أن لحم الإبل لا ينقض، فصلاته ليست باطلة؛ لأن هذا هو مقتضى علمه واجتهاده، أو جماعة مقلدين لمذهب الشافعي أبي حنيفة مالك ممن لا يرى النقض في لحم الإبل، ويرون أنه لا حرج عليهم حسب اعتقادهم تقليداً أو اجتهاداً هؤلاء صلاتهم صحيحة.\nلكن إنسان يعلم أن لحم الإبل ينقض وليس عنده شبهة في ذلك، ثم يتساهل تكون صلاته باطلة؛ لأنه صلى بغير وضوء. نعم.","link":"https://binbaz.org.sa/fatwas/5546/حكم-من-صلى-دون-ان-يتوضا-من-لحم-الجزور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07306.mp3","categories":["نواقض الوضوء"]},{"id":8503,"question":"أخت لنا من المغرب عائشة عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: الذين يعيشون لحظات غيبوبة هل ينتقض وضوءهم أو لا؟","title":"حكم وضوء المغمى عليه ومن أصيب بالصرع","answer":"الجواب:  هذا فيه تفصيل: مثل النوم إن كان شيء يسير ما يزيل الوعي، ولا يمنع الإحساس بخروج الحدث فلا يضر، كالنائم الذي ينعس يصيبه نعاس خفيف، ما يستغرق في نومه يسمع الناس يسمع الحركة هذا لا يضره، طهارته صحيحة حتى يعلم أنه خرج منه شيء، هكذا إذا كانت الغيبوبة لا تمنع الإحساس، مثل من تعاطى بعض الأدوية أو بعض الأشياء التي قد يحصل له بها شيء من الغيبوبة لكنها غير تامة، يحس معها بالحدث يسمع الكلام، هو مثل الناعس. أما إذا كانت غيبوبة تمنع شعوره بما يخرج منه كالسكران، والمصاب بمرض أفقده شعوره، صار في غيبوبة، هذا ينتقض وضوءه كالإغماء، كمن أغمي عليه بأي سبب من الأسباب، فإنه أعظم من النوم ينتقض معه الوضوء. نعم. المقدم: المصابون بالصرع سماحة الشيخ؟ الشيخ: كذلك يكون أعظم، إذا صرع ثم عافاه الله وزال عنه الصرع يتوضأ. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6571/حكم-وضوء-المغمى-عليه-ومن-اصيب-بالصرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12703.mp3","categories":["نواقض الوضوء"]},{"id":8519,"question":"هذه رسالة وردتنا من السائل الحاج شحات علي الملك ، مصري الجنسية من العباسية، ويعمل بالمنطقة الشرقية بالدمام، يقول: أنا أعمل بشركة وفيها مسلمين وغير مسلمين، وبعض الأوقات عندما أتوضأ ألامس بيدي بعض غير المسلمين، وأصلي بنفس الوضوء، هل صلاتي صحيحة أم أن علي إعادة الوضوء؟","title":"حكم الوضوء من لمس الكافر والمرأة","answer":"الجواب: لا، لمسك بعض الكفار بيدك بعد الوضوء لا ينقض الوضوء، حتى لمس المرأة على الصحيح لا ينقض الوضوء ولو كان عن تلذذ أو شهوة، الصحيح أنه لا ينقض الوضوء إلا إذا خرج شيء، وقد ذهب بعض أهل العلم إلى أن مس المرأة ينقض الوضوء مطلقاً، وقال آخرون: مسها بشهوة ينقض، والصحيح أنه لا ينقض الوضوء، وهكذا مس الكافر والكافرة لا ينقض الوضوء بل الوضوء صحيح، وإنما ينتقض بنواقضه المعروفة كالبول والغائط والريح والنوم وأكل لحم الإبل، هذا هو الذي ينقض الوضوء، أما مس المرأة أو مس الكافر أو مس الكافرة فليس من النواقض، لكن ليس لك أن تمس المرأة التي هي ليست محرماً لك، لا يجوز لك مس المرأة سواء كانت كافرة أو مسلمة، ليس لك مسها إلا إذا كانت زوجتك أو محرمك، وأما مس امرأة أجنبية منك كافرة أو مسلمة فليس لك ذلك، أما قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فهذا معناه الجماع، ليس المراد به اللمس باليد كما قاله جماعة من أصحاب النبي ﷺ وغيرهم، منهم ابن عباس رضي الله تعالى عنه فإنه فسرها بالجماع.\nوقد ذهب بعض أهل العلم إلى أن المراد به مس اليد كما قاله ابن مسعود ، ولكن الصحيح أن المراد به الجماع لا مس اليد. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6591/حكم-الوضوء-من-لمس-الكافر-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20308.mp3","categories":["نواقض الوضوء"]},{"id":8662,"question":"ملامسة الأشخاص الغُرْب (الأجانب) بعد الوضوء؟","title":"هل ينتقض الوضوء بلمس المرأة للرجل الأجنبي؟","answer":"الجواب: هذا فيه تفصيل: ليس للمرأة أن تلمس الرجل الغريب، ولكن لو لمسته لمست يده أو قدمه ما ينتقض وضوءها، وهكذا لو لمست يد أخيها أو يد أبيها أو يد عمها أو قبلت رأسه أو قبلت أنفه أو ما أشبه ذلك؛ لا ينتقض الوضوء كما تقدم. أما الغريب: الرجل الغريب ليس محرمًا لها، لا تلمس يده ولا غيره، لا تصافحه ولا تلمس شيئًا من بدنه، ولا يلمسها، إنما تسلم عليه من بعيد من غير لمس، كيف حالك يا فلان؟ وعليكم السلام، السلام عليكم، كيف أولادك؟ كيف أهلك؟ وما أشبه هذا من دون مصافحة ومن دون تكشف ولا ملامسة، بل تحتجب عنه، تكون محتجبة في وجهها وشعرها وبدنها، وتسلم عليه بالكلام وتسأله عن أهله بالكلام، وهو كذلك يسألها من دون ملامسة، لا تصافحه ولا يلمس يدها ولا تلمس يده ولا غير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6807/هل-ينتقض-الوضوء-بلمس-المراة-للرجل-الاجنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21412.mp3","categories":["نواقض الوضوء"]},{"id":8667,"question":"هذه رسالة وردتنا من المستمعة سامية موسى من جدة، والحقيقة أن الأخت سامية أرسلت بعدة أسئلة في هذه الرسالة، ربما لا نتمكن من عرضها جميعاً، تقول فيها: هناك أشياء كثيرة تحدث يومياً ولا أعرف هل تذهب الوضوء أم لا، سأذكرها في نقاط وأرجو أن تبينوا لي ما يذهب الوضوء منها وما لا يذهبه، مثلاً: ملامسة الأدوات الصحية في دورات المياه، كذلك الوقوف على بلاط دورة المياه حافية، ملامسة ملابس الطفل المبتلة بالبول، ملامسة الزوج أو تقبيله، الأكل أو الشرب بعد الوضوء مباشرة وقبل الصلاة؟الشيخ: لا تكثر .. أعد أعد، واحد واحد.المقدم: تقول: هذه الأشياء هل تذهب الوضوء أم لا؟الشيخ: أولها. ملامسة الأدوات الصحية وبلاط الحمام حافية؟","title":"حكم ملامسة المتوضئ الأدوات الصحية وبلاط الحمام","answer":"الجواب: هذا لا ينقض الوضوء، ملامسة الأشياء الصحية، الأدوات الصحية أو البلاط تكون حافية وليس فيه نجاسة لا ينقض الوضوء، فإن كان فيه نجاسة من بول، وطئت المرأة بول أو الرجل لا يضره لكن يغسل رجله، إذا وطئها وهو طاهر يخرج إلى محل طاهر ويغسل رجله، والحمد لله، ولا يضره ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/6803/حكم-ملامسة-المتوضى-الادوات-الصحية-وبلاط-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21408.mp3","categories":["نواقض الوضوء"]},{"id":8669,"question":"تقول: مداعبة الزوج هل تنقض الوضوء؟","title":"حكم مداعبة المرأة لزوجها والعكس وهما متوضئان","answer":"الجواب: مداعبة الزوج طيبة مشروعة، عليها أن تداعب زوجها ويداعبها هذا من الأنس مع الأهل، المداعبة من سنة الرسول ﷺ مع أهله، كان يداعبهن ويداعبنه عليه الصلاة والسلام ولا ينقض الوضوء، مجرد المداعبة، كالتقبيل والمضاحكة والملامسة والاضطجاع معها في لحافها أو في لحافه كل هذا لا بأس به، وكل هذا لا ينقض الوضوء إلا إذا حصل مس الفرج أو خرج شيء، إذا مس فرجها أو مست فرجه ينتقض الوضوء من مس الفرج، وهكذا لو خرج منه شيء مذي انتقض وضوءه، وهكذا هي إذا خرج منها مذي انتقض الوضوء، وإن خرج مني وجب الغسل منه أو منها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6809/حكم-مداعبة-المراة-لزوجها-والعكس-وهما-متوضىان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21414.mp3","categories":["نواقض الوضوء"]},{"id":8673,"question":"ملامسة الزوج أو تقبيله؟","title":"حكم ملامسة الزوج وتقبيله بعد الوضوء","answer":"الجواب: ملامسة الزوج أو تقبيله لا ينقض الوضوء على الصحيح، مس المرأة ومس المرأة للرجل عن شهوة أو عن تقبيل كل هذا لا ينقض الوضوء إلا إذا مست الفرج، أما إذا مست فرجها أو فرجه ينتقض الوضوء، وأما إذا مست بدنه أو مس بدنها أو قبلته أو قبلها فالصحيح أن هذا لا ينقض الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/6805/حكم-ملامسة-الزوج-وتقبيله-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21410.mp3","categories":["نواقض الوضوء"]},{"id":8675,"question":"ملامسة الزوج أو تقبيله؟","title":"حكم ملامسة الزوج وتقبيله بعد الوضوء","answer":"الجواب: ملامسة الزوج أو تقبيله لا ينقض الوضوء على الصحيح، مس المرأة ومس المرأة للرجل عن شهوة أو عن تقبيل كل هذا لا ينقض الوضوء إلا إذا مست الفرج، أما إذا مست فرجها أو فرجه ينتقض الوضوء، وأما إذا مست بدنه أو مس بدنها أو قبلته أو قبلها فالصحيح أن هذا لا ينقض الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/6805/حكم-ملامسة-الزوج-وتقبيله-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21410.mp3","categories":["نواقض الوضوء"]},{"id":8768,"question":"هذه رسالة وردتنا من مساعد بن مرزوق السناني من ينبع له فيها عدة أسئلة لكن نعرض بعضها حسب وقت البرنامج يقول: هل شحوم الإبل إذا وضعت بالطعام بصفة إدام تنقض الوضوء، أم لا؟","title":"حكم الوضوء من أكل شحوم الإبل","answer":"الجواب: الصحيح من أقوال العلماء أنها لا تنقض؛ لأنها لا تسمى لحم، الشحم ليس بلحم، والنبي ﷺ قال: توضئوا من لحوم الإبل والشحم عند العلماء ليس بلحم، وإنما اللحم الهبر المعروف، ولكن إذا توضأ من ذلك احتياطاً فحسن وإلا فلا يلزم. نعم.","link":"https://binbaz.org.sa/fatwas/6927/حكم-الوضوء-من-اكل-شحوم-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21809.mp3","categories":["نواقض الوضوء"]},{"id":9294,"question":"يسأل ثانية ويقول: إذا توضأ الرجل للصلاة وقابل في طريقه نصرانياً أو يهودياً وصافحه فهل يبطل وضوءه وما الحكم في دعوة المسيحي لتناول الطعام في بيت المسلم؟","title":"حكم وضوء من صافح كافرًا وحكم دعوته للطعام","answer":"الجواب: إذا صافح النصراني أو اليهودي أو غيرهما من الكفرة فالوضوء لا يبطل، هو على طهارته، لكن ليس له أن يصافحهم، وليس له أن يبدأهم بالسلام، يقول النبي ﷺ: لا تبدءوا اليهود ولا النصارى بالسلام، والمصافحة أشد، إذا كان لا يبدأ بالسلام فالمصافحة أشد، فلا يبدؤهم ولا يصافحهم، لكن إذا بدءوه بالسلام وصافحوه فلا بأس بالمقابلة، أما أنه يبدأ لا يبدأ.\nأما دعوته لوليمة دعوته للطعام هذا فيه تفصيل، إن كان دعاه لأجل ترغيبه في الإسلام ونصيحته وتوجيهه للإسلام لقصد صالح، أو لأنه ضيف نزل به، هذا لا بأس، أما أن يدعوه للطعام لأجل الصداقة والمؤانسة لا ما ينبغي له؛ لأنه بينه وبينهم العداوة والبغضاء. نعم.","link":"https://binbaz.org.sa/fatwas/7468/حكم-وضوء-من-صافح-كافرا-وحكم-دعوته-للطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23610.mp3","categories":["نواقض الوضوء","الأطعمة والأشربة"]},{"id":9364,"question":"ملامسة عورات الأطفال هل تنقض وضوء اللامس؟","title":"حكم مس عورات الأطفال بالنسبة لمن كان على طهارة","answer":"الجواب: نعم، عورة الطفل تنقض من مسها، إذا مستها أمه أو أبوه انتقض الوضوء؛ للحديث: من مس الذكر فليتوضأ نعم.","link":"https://binbaz.org.sa/fatwas/7528/حكم-مس-عورات-الاطفال-بالنسبة-لمن-كان-على-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18605.mp3","categories":["نواقض الوضوء"]},{"id":9458,"question":"يسأل أيضاً ويقول: أحياناً أشعر ببلل في سراويلي وأجد سائلاً قليل مائي يخرج مني، وقد يخرج أثناء الصلاة أو يخرج في مكان لا أستطيع فيه نضح سراويلي، علماً بأن هذا السائل لا يخرج نتيجة لمداعبة ولا تفكير، فما هو هذا السائل؟ وماذا علي أن أفعل تجاه هذا الأمر؟","title":"حكم ما يخرج من الذكر بعد الوضوء وأثناء الصلاة","answer":"الجواب: هذا السائل حكمه حكم البول، وعليك أن تستنجي منه، وتغسل ما أصاب سراويلك أو إزارك، وإذا حدث في الصلاة بطلت الصلاة، وإذا حدث بعد الوضوء بطل الوضوء؛ لأن حكمه حكم البول، إلا أن يكون مستمراً معك على سبيل السلس، إذا كان مستمراً لا ينقطع إلا الشيء اليسير وإلا في الغالب أنه معك، فهو معفو عنه، إذا توضأت بعد دخول الوقت لا يضرك إذا صليت به، لكن إذا كان ليس بمستمر إنما يحدث بعض الأحيان، فهذا متى حدث ينقض الوضوء ويبطل الصلاة إذا وقع فيها، والواجب عليك أن تغسل ما أصاب سراويلك أو إزارك أو قميصك وتستنجي منه أيضاً وتعيد الوضوء متى حدث، إلا أن يكون أمرًا مستمرًا كالبول المستمر وكالمستحاضة، فهذا إذا كان مستمرًا معه يستنجي عند دخول الوقت، ويغسل ما أصاب ثيابه، ثم بعد هذا إذا خرج منه شيء في أثناء الوقت أو في أثناء الصلاة يكون معفواً عنه، كصاحب السلس المستمر، وكالمرأة المستحاضة بالدم الدائم، نسأل الله للجميع العافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7616/حكم-ما-يخرج-من-الذكر-بعد-الوضوء-واثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25507.mp3","categories":["نواقض الوضوء"]},{"id":9503,"question":"يسأل الأخ علي عبدالرحمن راشد ثانياً ويقول: إذا أحسست بنزول قطرة من بول أثناء الصلاة فهل تبطل صلاتي، وماذا أعمل؟","title":"حكم من أحس بنزول قطرة من البول أثناء الصلاة","answer":"الجواب: إذا علمت ذلك يقيناً فلا تصح الصلاة، بطلت الصلاة، سئل النبي ﷺ قال له رجل: يا رسول الله! الرجل يجد الشيء في الصلاة، فقال ﷺ: لا ينصرف حتى يسمع صوتاً أو يجد ريحاً وفي اللفظ الآخر: سئل ﷺ عن الرجل يحس في بطنه شيئاً قال: لا يخرجن من المسجد حتى يسمع صوتاً أو يجد ريحاً يعني: لا يخرج حتى يتحقق أنه أحدث ريحاً أو بولاً أو غير ذلك، فإذا علم المصلي أنه خرج منه ريح أو بول أو غيرهما بطلت صلاته، وعليه أن يستأنف الوضوء والصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7668/حكم-من-احس-بنزول-قطرة-من-البول-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24302.mp3","categories":["نواقض الوضوء"]},{"id":9632,"question":"الرسالة السادسة وردت من فضل أحمد سوري مقيم في الكويت، يقول في رسالته: إن مذهب الإمام الشافعي رحمه الله يقول: بأن لمس النساء ينقض الوضوء، فمن هن هؤلاء النساء؟ وهل لمس ذوات المحارم اللاتي لم يبلغن ينقض الوضوء أفيدونا أفادكم الله؟","title":"حكم مس المرأة","answer":"الجواب: لمس النساء في نقضه الوضوء خلاف بين أهل العلم، من أهل العلم من قال: إنه ينقض مطلقاً كـالشافعي رحمه الله، ومنهم من قال: لا ينقض مطلقاً كـأبي حنيفة رحمه الله، ومنهم من قال: ينقض بالشهوة إن لمستها بتلذذ وشهوة انتقض وإلا فلا كـأحمد رحمه الله.\nوالصواب في هذه المسألة الذي يقوم عليه الدليل: هو أن مس المرأة لا ينقض الوضوء مطلقاً، سواء كان عن شهوة وتلذذ أم لا هذا هو الصواب؛ لأنه ﷺ: قبل بعض نسائه ثم صلى ولم يتوضأ ولأن الأصل سلامة الطهارة، وبراءة الذمة من وضوء آخر، فلا يجب الوضوء إلا بدليل سليم لا معارض له؛ ولأن النساء موجودات في كل بيت غالباً والبلوى تعم بمسهن من أزواجهن وغير أزواجهن، فلو كان ينقض الوضوء لأوضحه النبي ﷺ وبينه بياناً واضحاً لا يخفى.\nوأما قوله جل وعلا: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] وفي قراءة أخرى: أَوْ لمَسْتُمُ النِّسَاءَ فالمراد به: الجماع، كنى الله به عن الجماع؛ لأنه سبحانه يكني عن الجماع بالمسيس، هكذا قال ابن عباس رضي الله عنهما وجماعة من أهل العلم وهو الصواب: أن المراد بالملامسة الجماع، أما مسها باليد فإنه لا ينقض الوضوء مطلقاً في أصح أقوال العلماء في أصح الأقوال الثلاثة، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7802/حكم-مس-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25010.mp3","categories":["نواقض الوضوء"]},{"id":9793,"question":"وهذه رسالة من سائلة لم تذكر اسمها بل رمزت إليه بـ (س. ل. ن) من الرياض، تقول: أنا أبلغ من العمر ثمانية عشر عامًا ومنذ سنتين إذا شرعت في الصلاة أشعر كأنه يخرج مني بول وهذا مستمر معي دائمًا فأفيدوني في ذلك؟","title":"حكم من شك بخروج البول أثناء الصلاة","answer":"الجواب: هذا لا يقع به شيء، هذه وساوس فصلاتك صحيحة ولا يضرك هذا الوسواس إلا إذا جزمت وتحققت أنه خرج منك البول، فإذا جزمت بهذا وأن البول خرج وأنت في الصلاة فأعيدي الوضوء وأعيدي الصلاة، أما مجرد أوهام ووساوس فإنها لا يلتفت إليها والصلاة صحيحة وينبغي لك أن تقطعي هذا الوسواس وأن تشتغلي بالصلاة وأن تبتعدي عن هذه الوساوس حتى لا تتكرر عليك. نعم.","link":"https://binbaz.org.sa/fatwas/7960/حكم-من-شك-بخروج-البول-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19609.mp3","categories":["مبطلات الصلاة","نواقض الوضوء"]},{"id":9832,"question":"وهذه رسالة من سائلة لم تذكر اسمها تقول: عندما أصلي صلاة الضحى وأنتظر صلاة الظهر يغالبني نعاس، فهل ينتقض وضوئي به أم لا؟","title":"حكم الوضوء من النعاس","answer":"الجواب: النعاس لا ينقض الوضوء، إذا كان نعاس على اسمه ليس فيه نوم ثقيل يذهب معه الشعور؛ فإن هذا لا ينقض الوضوء، النعاس كون الإنسان يحس بالنوم ويخفض رأسه بعض الأحيان، ولكن يسمع الناس ويسمع الكلام ولا يزول شعوره بالكلية، فهذا لا ينقض الوضوء، وقد كان الصحابة  ينتظرون العشاء على عهد النبي ﷺ فتخفق رءوسهم من النعاس ثم يصلون ولا يتوضئون.\nأما النوم الثقيل الذي يذهب معه الشعور فهذا ينقض الوضوء، فينبغي لك أن تنتبهي لهذا الأمر، فالنوم الثقيل الذي يزول معه الشعور هذا ينقض وضوءك وعليك الوضوء، أما مجرد النعاس الذي معه الإحساس ومعه الشعور بمن حولك ممن يتكلم أو يمشي أو نحو ذلك فهذا لا ينقض الوضوء. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7996/حكم-الوضوء-من-النعاس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19802.mp3","categories":["نواقض الوضوء"]},{"id":9887,"question":"وهذه رسالة وردتنا من أبو بكر صالح داود حسين سوداني مقيم بمنطقة حفر الباطن بالمملكة، يقول: إذا كان الإنسان توضأ ثم شرب الدخان وصلى مباشرة وربما يؤم الناس، وقد قلنا لمن يفعل ذلك: إن الدخان ينقض الوضوء فقالوا لنا: ليس بصحيح، فما الحكم في هذا؟","title":"هل ينتقض الوضوء بشرب الدخان وما حكم تعاطي القات؟","answer":"الجواب: الدخان لا ينقض الوضوء، ولكنه محرم خبيث يجب تركه، لكن لو شربه وصلى لم تبطل صلاته ولم يبطل وضوءه؛ لأنه حشيش من الحشيش المعروف، لكنه حرم لمضرته.\nفالواجب على متعاطيه أن يحذره وأن يدعه ويتقي شره، فلا يجوز له شراؤه ولا استعماله، ولا تجوز التجارة فيه، بل يجب على من يتعاطى ذلك أن يتوب إلى الله، وأن يدع التجارة فيه، يقول الله سبحانه: يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ [المائدة:4] قال الله : قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] فالله  لم يحل لنا إلا الطيبات، وهي المغذيات النافعات.\nوقال سبحانه في وصف النبي ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157].\nولا ريب أن الدخان والمسكرات كلها من الخبائث، وهكذا الحشيشة المسكرة المعروفة من الخبائث، فيجب ترك ذلك.\nوهكذا القات المعروف في اليمن من الخبائث؛ لأنه يضر ضرراً كبيراً ويترتب عليه تعطيل الأوقات وضياع الأوقات، وقد ذكر جمع من أهل المعرفة به، من أبناء اليمن وغيرهم فيه مضار كثيرة، فالواجب على من يتعاطاه أن يدعه، وأن يتوب إلى الله من ذلك، وأن يحفظ صحته، وماله وأوقاته فيما ينفعه، الواجب على المؤمن ألا يضيع أوقاته في غير طائل، وهذا القات يضيع الأوقات ويضر متعاطيه، ويتلف ماله في غير طائل.\nفالواجب على المؤمن أن يحذر ما يضره في دينه ودنياه، ومن ذلك الدخان والقات، وأنواع المسكرات يجب الحذر منها كلها مع التوبة الصادقة النصوح مما سبق، ولا تجوز التجارة في ذلك، بل يجب ترك ذلك وعدم التجارة فيه؛ لأنه يضر المسلمين، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8051/هل-ينتقض-الوضوء-بشرب-الدخان-وما-حكم-تعاطي-القات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26408.mp3","categories":["الأطعمة والأشربة","نواقض الوضوء"]},{"id":9905,"question":"تقول السائلة: هناك كحل على شكل قلم هل يمنع هذا الكحل من وصول الماء إلى الجلد عند الوضوء؟","title":"حكم الكحل والحناء عند الوضوء.","answer":"الجواب: لا يمنع، مجرد الكحل هذا صبغ ما يمنع، والحناء في اليد صبغ، أما إذا كان له جسم يمنع الماء يزال الجسم، إذا كان هناك متلبد جسم له متلبد من الحناء أو من الكحل يزال عند الوضوء، أما مجرد وجود سواد في كحل أو حمرة حناء أو شبه ذلك هذا لا يمنع، لا يمنع في الحناء أو في الرجل أو الكحل في العين هذا لا يمنع .. الوضوء؛ لأنه صورة لا جسم لها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8073/حكم-الكحل-والحناء-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27317.mp3","categories":["نواقض الوضوء"]},{"id":10099,"question":"تقول عن نفسها: أستعمل الكحل السائل، والكحل السائل هو عبارة عن خط أسود نستطيع أن نبعده ويصبح على شكل شريط وبعضه يتراكم، فهل يصح الوضوء مع استعمال هذا الكحل.","title":"الكحل وتأثيره في الوضوء","answer":"","link":"https://binbaz.org.sa/fatwas/8268/الكحل-وتاثيره-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27701.mp3","categories":["نواقض الوضوء"]},{"id":10245,"question":"من جيزان رسالة بتوقيع أحد الإخوة يقول: (ع. حسن ) يسأل يقول: هل أكل لحم الجزور ينقض الوضوء؟","title":"حكم وضوء من أكل لحم الإبل","answer":"الجواب: نعم أكل لحم الإبل ينقض الوضوء، لقول النبي ﷺ توضئوا من لحوم الإبل ولا توضئوا من لحوم الغنم ، ولحوم الإبل الهبر.... أما الشحمة أو الكرش أو المصير أو المرق أو اللبن هذا لا ينقض الوضوء، الذي ينقض اللحم. نعم.\nالمقدم: جزاكم الله خيراً، بالنسبة للكبد والطحال والكلى سماحة الشيخ؟\nالشيخ: لا تنقض وإن توضأ احتياطًا حسن، أما المرق واللبن فلا ينقض. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8416/حكم-وضوء-من-اكل-لحم-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27903.mp3","categories":["نواقض الوضوء"]},{"id":10344,"question":"يقول: عند الوضوء وإذا استنشقت وجئت لأستنثر يخرج دم فكيف أتصرف وهل الوضوء حينئذ صحيح؟","title":"حكم خروج دم عند الاستنثار من الوضوء","answer":"الجوب: الوضوء صحيح وتغسل ما خرج من الدم والوضوء صحيح، إذا كان الشيء يسيراً، أما إن كان كثيراً فتعتني بإزالته وإيقافه ثم تكمل الوضوء، أما إن كان يسيراً فإنك تزيله بالغسل وتستمر في إكمال الوضوء.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8515/حكم-خروج-دم-عند-الاستنثار-من-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31602.mp3","categories":["نواقض الوضوء"]},{"id":10495,"question":"هل مس يد المرأة ليد الرجل وليس هناك قصد، هل يؤثر ذلك على ضوئهما أو لا؟","title":"حكم وضوء من مس المرأة","answer":"الجواب: مس المرأة فيه تفصيل: وله ثلاث حالات: إحدها: أن يمسها بشهوة، والثانية: أن لا يمسها بشهوة، بل مس عادي، والثالثة: القول الثالث: أنه سواء بشهوة أو بغير شهوة لا يضر، والصواب أن مسها لا ينقض الوضوء، سواء كان عن تلذذ أو عن غير تلذذ، هذا هو الصواب، وأما قوله سبحانه: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به الجماع: جامعتم النساء، فمس المرأة، إذا مسها يعني لغير شهوة لا ينقض الوضوء، وهكذا لو مسها متلذذاً مس يدها أو قبلها فإنه لا ينقض الوضوء لا ينتقض وضوءه بذلك، قد قالت عائشة رضي الله عنها: إن النبي ﷺ كان يقبلها ثم يصلي ولا يتوضأ.\nفالمقصود أن تقبيل المرأة أو مس يدها أو قدمها أو وجهها لا ينقض الوضوء على الصحيح مطلقًا، إلا إذا خرج منه شيء كالمذي انتقض الوضوء، أما ما دام مساً من دون شيء لا يخرج شيء، فالصواب أن هذا المس لا ينقض الوضوء؛ لحديث عائشة رضي الله عنها: كان يقبل بعض نسائه ثم يصلي ولا يتوضأ اللهم صل عليه ....... . نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8670/حكم-وضوء-من-مس-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28203.mp3","categories":["نواقض الوضوء"]},{"id":10566,"question":"أخيراً يسأل ويقول: هل التبسم في الصلاة يفسدها؟","title":"هل التبسم في الصلاة يفسدها؟","answer":"الجواب: ليس يفسدها لا يفسدها، التبسم لا يفسدها، لكن الضحك يفسدها، الضحك الذي له صوت الذي يظهر له صوت هذا يفسدها، وهكذا الكلام إذا تعمد الكلام وهو يعلم تحريمه أفسدها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8749/هل-التبسم-في-الصلاة-يفسدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32309.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":10648,"question":"له سؤال ثاني يقول: ما الحكمة من أن لحم الجزور ينقض الوضوء؟","title":"الحكمة في كون لحم الجزور ينقض الوضوء","answer":"الجواب: الله أعلم، أمرنا الرسول ﷺ أن نتوضأ وعلينا أن نتوضأ، الرسول ﷺ أمرنا أن نتوضأ من لحوم الإبل فعلينا أن نتوضأ ولو لم نعرف الحكمة، فربنا حكيم عليم لا يأمر إلا عن حكمة ولمصلحة سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/8825/الحكمة-في-كون-لحم-الجزور-ينقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28509.mp3","categories":["نواقض الوضوء"]},{"id":10662,"question":"قرأت لصاحب فقه السنة: أن الدم لا يفسد الوضوء، واستدل بأعمال بعض الصحابة حيث صلى بعضهم وجروحهم تثعب دماً، وقد قال: إن الحجامة لا تفسد الصوم، فما قولكم في هذا؟","title":"حكم وضوء من احتجم أو جرح وخرج منه دم","answer":"الجواب: هذه المسألة خلاف بين أهل العلم، والأرجح أنه إذا كان الشيء قليل من الدم لا ينقض الوضوء يعفى عن اليسير، أما الكثير فالأحوط للمؤمن أن يتوضأ؛ خروجاً من خلاف العلماء؛ لأن الأدلة ........................ تتوضأ لوقت كل صلاة وتصلي، هكذا من معه عذره الدائم يتوضأ لكل صلاة ..................................\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8845/حكم-وضوء-من-احتجم-او-جرح-وخرج-منه-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32911.mp3","categories":["نواقض الوضوء"]},{"id":10670,"question":"قرأت لصاحب فقه السنة: أن الدم لا يفسد الوضوء، واستدل بأعمال بعض الصحابة حيث صلى بعضهم وجروحهم تثعب دماً، وقد قال: إن الحجامة لا تفسد الصوم، فما قولكم في هذا؟","title":"حكم وضوء من احتجم أو جرح وخرج منه دم","answer":"الجواب: هذه المسألة خلاف بين أهل العلم، والأرجح أنه إذا كان الشيء قليل من الدم لا ينقض الوضوء يعفى عن اليسير، أما الكثير فالأحوط للمؤمن أن يتوضأ؛ خروجاً من خلاف العلماء؛ لأن الأدلة ........................ تتوضأ لوقت كل صلاة وتصلي، هكذا من معه عذره الدائم يتوضأ لكل صلاة ..................................\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8845/حكم-وضوء-من-احتجم-او-جرح-وخرج-منه-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32911.mp3","categories":["نواقض الوضوء"]},{"id":10784,"question":"المستمع عبدالمحبوب سيف علي بعث بهذه الرسالة يسأل في سؤالها الأول عن مس القبل أو الدبر؟ وما حكمه في الوضوء؟","title":"حكم وضوء من مس فرجه بيده","answer":"الجواب: من مس فرجه دبراً كان أو قبلاً انتقض وضوءه؛ لقول النبي ﷺ: من أفضى بيده إلى فرجه ليس دونهما حائل فقد وجب عليه الوضوء ، وفي اللفظ الآخر: من مس ذكره فليتوضأ فإذا مس الرجل فرجه دبراً أو قبلاً انتقض وضوؤه وهكذا المرأة. نعم.","link":"https://binbaz.org.sa/fatwas/8959/حكم-وضوء-من-مس-فرجه-بيده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35005.mp3","categories":["نواقض الوضوء"]},{"id":10786,"question":"أيضاً يسأل عن خروج الدم من جرح في الجسم هل ينقض الوضوء، أفيدونا أفادكم الله؟","title":"حكم وضوء من خرج منه دم","answer":"الجواب: أما الدم القليل فلا ينقض والرعاف القليل لا ينقض، أما إذا كثر فالأحوط الوضوء؛ لأن فيه خلافاً بين أهل العلم، منهم من رأى النقض، ومنهم من لم ير النقض، والآثار في هذا والأحاديث فيها بعض التعارض وليس في المقام حديث صحيح يدل على النقض لكن من باب الاحتياط ومن باب دع ما يريبك إلى ما لا يريبك؛ إذا كثر فإنه يتحفظ من هذا الدم ويتوضأ هذا هو الأفضل والأحوط له، خروجاً من خلاف العلماء وعملاً بالنصوص كلها.\nأما إن كان الشيء قليلاً فإنه يعفى عنه، نقطات قليلة من الرعاف والنقاط القليلة من الجرح وهكذا عصر بثرة في العين وما يخرج من الأسنان بعض الأحيان عند السواك أو نحوه كل هذا يعفى عنه، ولا حرج فيه. نعم.","link":"https://binbaz.org.sa/fatwas/8960/حكم-وضوء-من-خرج-منه-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35006.mp3","categories":["نواقض الوضوء"]},{"id":11163,"question":"إذا غسلت طفلًا وأنا متوضئة، فهل ينتقض وضوئي؟","title":"حكم وضوء من غسلت طفلاً","answer":"الجواب:  نعم إذا مسست فرج الطفل ينتقض الوضوء، فإن مس الفرج من الطفل ومن الكبير ينقض الوضوء، إذا كان من دون حائل، أما مع الحائل ومن وراء الحائل فلا ينقض الوضوء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9349/حكم-وضوء-من-غسلت-طفلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37113.mp3","categories":["نواقض الوضوء"]},{"id":11476,"question":"البعض يقول: إن لمس المرأة ينقض الوضوء، والبعض منهم يقول: إن كانت صغيرة لا تنقض، أي: إذا كانت دون السابعة، فما هو توجيه سماحة الشيخ، جزاكم الله خيرًا؟","title":"حكم الوضوء من مس المرأة","answer":"الجواب:  اختلف العلماء في مس المرأة هل ينقض الوضوء؟ على أقوال ثلاثة: أحدها: أنه ينقض الوضوء مطلقًا، لعموم قوله -جل وعلا-: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43]، وحملوا على الملامسة اللمس باليد يعني. والقول الثاني: أنه ينقض إذا كان معه شهوة تلذذ؛ لأنه ثبت أن النبي ﷺ: كان يلمس نساءه ولا يتوضأ، وكان يغمز قدمي عائشة حتى تكفها وهو يصلي فدل ذلك على أنه إذا كان بغير شهوة لا ينقض. والقول الثالث: أنه لا ينقض مطلقًا، لمس المرأة لا ينقض مطلقًا سواءً بشهوة، أو بغير شهوة، وهذا هو الراجح هو الصواب أن لمس المرأة لا ينقض الوضوء في أرجح أقوال العلماء؛ لأن الرسول ﷺ: كان يقبل بعض نسائه، ثم يصلي، ولا يتوضأ والتقبيل يكون في الغالب عن تلذذ.  فالحاصل: أن الصواب أن لمس المرأة لا ينقض الوضوء سواءً كان عن تلذذ وشهوة، أو عن غير ذلك، إلا إذا خرج منه مذي ينقض الوضوء، يغسل ذكره ويتوضأ، أما إذا مسها بشهوة، أو بغير شهوة، ولم يخرج شيء فإن وضوءه صحيح ولا ينتقض. أما قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43]، في سورة النساء وفي سورة المائدة فالمراد بذلك الجماع، كناية عن الجماع، أو لامستم أي: جامعتم، ليس المراد باللمس باليد المراد الجماع، والله يكني عن الجماع بالملامسة وبالمسيس  هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9660/حكم-الوضوء-من-مس-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38206.mp3","categories":["نواقض الوضوء"]},{"id":11479,"question":"البعض يقول: إن لمس المرأة ينقض الوضوء، والبعض منهم يقول: إن كانت صغيرة لا تنقض، أي: إذا كانت دون السابعة، فما هو توجيه سماحة الشيخ، جزاكم الله خيرًا؟","title":"حكم الوضوء من مس المرأة","answer":"الجواب:  اختلف العلماء في مس المرأة هل ينقض الوضوء؟ على أقوال ثلاثة: أحدها: أنه ينقض الوضوء مطلقًا، لعموم قوله -جل وعلا-: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43]، وحملوا على الملامسة اللمس باليد يعني. والقول الثاني: أنه ينقض إذا كان معه شهوة تلذذ؛ لأنه ثبت أن النبي ﷺ: كان يلمس نساءه ولا يتوضأ، وكان يغمز قدمي عائشة حتى تكفها وهو يصلي فدل ذلك على أنه إذا كان بغير شهوة لا ينقض. والقول الثالث: أنه لا ينقض مطلقًا، لمس المرأة لا ينقض مطلقًا سواءً بشهوة، أو بغير شهوة، وهذا هو الراجح هو الصواب أن لمس المرأة لا ينقض الوضوء في أرجح أقوال العلماء؛ لأن الرسول ﷺ: كان يقبل بعض نسائه، ثم يصلي، ولا يتوضأ والتقبيل يكون في الغالب عن تلذذ.  فالحاصل: أن الصواب أن لمس المرأة لا ينقض الوضوء سواءً كان عن تلذذ وشهوة، أو عن غير ذلك، إلا إذا خرج منه مذي ينقض الوضوء، يغسل ذكره ويتوضأ، أما إذا مسها بشهوة، أو بغير شهوة، ولم يخرج شيء فإن وضوءه صحيح ولا ينتقض. أما قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43]، في سورة النساء وفي سورة المائدة فالمراد بذلك الجماع، كناية عن الجماع، أو لامستم أي: جامعتم، ليس المراد باللمس باليد المراد الجماع، والله يكني عن الجماع بالملامسة وبالمسيس  هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9660/حكم-الوضوء-من-مس-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38206.mp3","categories":["نواقض الوضوء"]},{"id":11912,"question":"هل لمس المرأة يبطل الوضوء؟","title":"حكم وضوء من لمس امرأة بشهوة وغيرها","answer":"الجواب: الصواب أنه لا يبطل الوضوء مطلقًا، ولو كان بشهوة، ولو كان بتلذذ، ولو قبلة لزوجتك مثلًا، أو مسها، الوضوء صحيح، هذا الصواب. وقد ذهب بعض أهل العلم إلى أنه ينتقض الوضوء إذا كان بشهوة، والصواب أنه لا ينتقض الوضوء بذلك، بل وضوؤه صحيح؛ لأنه ثبت عن النبي ﷺ أنه قبل بعض نساءه، ثم صلى، ولم يتوضأ ﷺ.  وأما قوله تعالى: أَوْ لاَمَسْتُمُ النِّسَاء[المائدة:6]، فهذا المراد به الجماع في أصح قولي العلماء، كما قاله ابن عباس وجماعة، المراد به الجماع، لامستم يعني: جامعتم، الله  يكني بالملامسة، والمسيس عن الجماع؛ ولهذا قال قبل ذلك، أو جاء أحدٌ منكم من الغائط، هذا الحدث الأصغر، وقوله أَوْ لاَمَسْتُمُ النِّسَاء هذا الحدث الأكبر -الجماع- أما مسها بقبلة، أو بيدٍ؛ فهذا لا يبببؤؤ نقض الوضوء مطلقًا عن شهوة، أو عن غير شهوة، لا ينقض الوضوء ووضوؤه صحيح، هذا هو الصواب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10096/حكم-وضوء-من-لمس-امراة-بشهوة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42613.mp3","categories":["نواقض الوضوء"]},{"id":12023,"question":"يدعي البعض بأن قتل البراغيث، أو القمل يبطل الوضوء، فهل هذا صحيح؟","title":"حكم وضوء من قتل البراغيث والقمل","answer":"الجواب:  ليس بصحيح، لا حرج في ذلك قتل البرغوث، أو القمل، أو العقرب عنده حوله وهو يصلي، أو حية ضربها وقتلها، النبي ﷺ قال: اقتلوا الأسودين في الصلاة: الحية، والعقرب فكيف بالبرغوث، والبعوض، لا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10208/حكم-وضوء-من-قتل-البراغيث-والقمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43214.mp3","categories":["نواقض الوضوء"]},{"id":12036,"question":"المستمع عبدالله أحمد بعث يسأل ويقول: هل لمس المرأة ينقض الوضوء؟","title":"حكم وضوء من لمس المرأة","answer":"الجواب:  لمس المرأة فيه اختلاف بين العلماء: منهم من قال: ينقض الوضوء، ومنهم من قال: لا ينقض الوضوء، ومنهم من فصل فقال: إن مسها بشهوة بتلذذ؛ انتقض وضوءه، وإلا فلا، والصواب أنه لا ينقض الوضوء مطلقًا، مس المرأة لا ينقض الوضوء مطلقًا، هذا هو الصواب، هذا هو الراجح؛ لأن الأصل عدم نقض الوضوء بذلك؛ ولأنه ﷺ كان يقبل بعض نسائه، ثم يصلي ولا يتوضأ، ولم يأمر الناس بالوضوء من مس المرأة، ولو كان مسها ينقض لأمر به الناس، الله بعثه معلمًا، ومرشدًا -عليه الصلاة والسلام- ولم يتوفه الله إلا وقد بلغ البلاغ المبين -عليه الصلاة والسلام- فلو كان مس المرأة ينقض الوضوء لبينه النبي، عليه الصلاة والسلام. أما قول الله  فيما يوجب الوضوء: أَوْ لامَسْتُمُ النِّسَاءَ [المائدة:6] فالمراد بذلك: الجماع، قال تعالى: وَإِنْ كُنْتُمْ مَرْضَى أَوْْ عَلَى سَفَرٍ أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ أَوْ لامَسْتُمُ النِّسَاءَ [المائدة:6] قوله سبحانه: أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ [المائدة:6] هذا فيه الوضوء الحدث الأصغر، قوله: أَوْ لامَسْتُمُ النِّسَاءَ [المائدة:6] هذا فيه الجنابة يعني: إتيان النساء، والله يكني عن الجماع بالملامسة، والمسيس، وليس المراد مس اليد، ولا مس قبلة، المراد الجماع، هذا هو المعنى الصحيح في تفسير الآية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10221/حكم-وضوء-من-لمس-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43305.mp3","categories":["نواقض الوضوء"]},{"id":12112,"question":"تقول: سمعنا في برنامج نور على الدرب أن لحم الإبل ناقض للوضوء، هل تصح الصلاة على بساط من وبر الإبل، ثم يا حبذا لو تفضلتم ببيان هذا الأمر وذكرتم لنا الدليل، وهل اللبن أيضًا يؤثر في الوضوء؟ جزاكم الله خيرًا.","title":"حكم الوضوء من لحم الإبل ولبنها ومرقها","answer":"الجواب:  نعم. لحم الإبل ينقض الوضوء؛ لأنه صﷺ أمر في الحديث الصحيح بالوضوء من لحم الإبل، وسئل عن لحم الغنم فقال: إن شئت وقال: توضؤوا من لحوم الإبل فدل على وجوب الوضوء من لحوم الإبل، يعني: الهبر، أما الفرش والكرش والشحم فلا وضوء منه، ولو توضأ؛ فحسن، احتياطًا، أما اللبن والمرق؛ فلا وضوء منه، اللبن لبن الإبل، والمرق؛ فليس منه الوضوء، إنما الوضوء من اللحم، لصحة الأحاديث ذلك عن النبي -عليه الصلاة والسلام- وأما بقية اللحوم كالبقر والغنم والصيود؛ فلا وضوء منها، إنما هذا خاص بالإبل خاصة، فمن أكل لحم الإبل؛ فعليه الوضوء، يعني: التمسح، يعني: يتمضمض، ويستنشق، ويغسل وجهه، ويغسل يديه مع المرفقين، يمسح رأسه مع أذنيه، ويغسل رجليه، وليس عليه استنجاء، الاستنجاء من البول والغائط خاصة، أما لحم الإبل والريح، وهكذا النوم، هكذا مس الفرج، هذا ليس فيه إلا التمسح، الوضوء الذي هو غسل الوجه واليدين ومسح الرأس وغسل الرجلين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10297/حكم-الوضوء-من-لحم-الابل-ولبنها-ومرقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43715.mp3","categories":["نواقض الوضوء"]},{"id":12537,"question":"له سؤال آخر يقول: هل وقوع النجاسة على جسم الإنسان تلزمه بإعادة الوضوء، أم أنه يكفي إزالة النجاسة، والصلاة دون إعادة الوضوء؟","title":"أثر وقع النجاسة على وضوء الإنسان","answer":"الجواب:  إذا وقعت على جسم الإنسان نجاسة بعد الوضوء، بأن وقع عليه شيء من بول صبي، أو غير ذلك من أنواع النجاسة؛ فإنه يغسل محل النجاسة، ويكفي، ولا يعيد الوضوء، بل يغسل ما أصاب النجاسة من ثوب، أو بدن، وليس عليه أن يعيد الوضوء. أما إذا كانت النجاسة من نفسه بأن خرج منه البول؛ فهذا يستنجي، ويعيد الوضوء، أما لو أصابه نجاسة من طفل عنده، طفل، أو من غيره، أو سقط عليه دم؛ يغسل ما أصابه، ويكفي، والوضوء صحيح. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10744/اثر-وقع-النجاسة-على-وضوء-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40906%20%20.mp3","categories":["النجاسات وإزالتها","نواقض الوضوء"]},{"id":13563,"question":"يقول في آخر أسئلته هذا السائل: ما حكم من يحمل في جيبه الدخان، أو السجائر أثناء تأديته للصلاة؟ وهل التدخين ينقض الوضوء؟","title":"حكم وضوء وصلاة من صلى وفي جيبه دخان","answer":"الجواب: صلاته صحيح، لكن يجب عليه التوبة إلى الله، ويجب عليه ترك التدخين، والتدخين لا ينقض الوضوء، لكن يجب عليه تركه؛ لأنه محرم، وفيه أضرار كثيرة، وشر كثير. فالواجب ترك التدخين، لكن لو صلى وفي جيبه شيء؛ صلاته صحيحة، يعني: ليس بنجس، ليس بنجس من جهة إفساد الصلاة، وإن كان نجسًا من حيث المعنى، لكن ليس نجسًا من جنس البول والغائط، لا. لكنه نجس من حيث المعنى، يعني: قذر من حيث أنه يؤذي ويضر، لكن لو صلى في جيبه شيء؛ صلاته صحيحة إلا أن عليه التوبة إلى الله من استعماله، والحذر من ذلك، والله -جل وعلا- يتوب على التائبين . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11890/حكم-وضوء-وصلاة-من-صلى-وفي-جيبه-دخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52209.mp3","categories":["الأطعمة والأشربة","نواقض الوضوء"]},{"id":13565,"question":"يقول في آخر أسئلته هذا السائل: ما حكم من يحمل في جيبه الدخان، أو السجائر أثناء تأديته للصلاة؟ وهل التدخين ينقض الوضوء؟","title":"حكم وضوء وصلاة من صلى وفي جيبه دخان","answer":"الجواب: صلاته صحيح، لكن يجب عليه التوبة إلى الله، ويجب عليه ترك التدخين، والتدخين لا ينقض الوضوء، لكن يجب عليه تركه؛ لأنه محرم، وفيه أضرار كثيرة، وشر كثير. فالواجب ترك التدخين، لكن لو صلى وفي جيبه شيء؛ صلاته صحيحة، يعني: ليس بنجس، ليس بنجس من جهة إفساد الصلاة، وإن كان نجسًا من حيث المعنى، لكن ليس نجسًا من جنس البول والغائط، لا. لكنه نجس من حيث المعنى، يعني: قذر من حيث أنه يؤذي ويضر، لكن لو صلى في جيبه شيء؛ صلاته صحيحة إلا أن عليه التوبة إلى الله من استعماله، والحذر من ذلك، والله -جل وعلا- يتوب على التائبين . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11890/حكم-وضوء-وصلاة-من-صلى-وفي-جيبه-دخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52209.mp3","categories":["الأطعمة والأشربة","نواقض الوضوء"]},{"id":13671,"question":"بعد ذلك ننتقل إلى القصيم والسائل: (أ. أ) يقول: سماحة الشيخ! ما الحكمة من أننا نتوضأ إذا أكلنا لحم الجزور عن بقية الأغنام؟ جزاكم الله خيرًا.","title":"الحكمة من الوضوء من أكل لحم الجزور","answer":"الجواب: الله أعلم، المشهور عند العلماء أنها تعبدية، أمرنا الله بها تعبدًا؛ فعلينا أن نمتثل أمر الله  ولو لم نعلم الحكمة، المشهور عند أهل العلم أن هذا تعبد، لا نعلم الحكمة فيه، والله -جل وعلا- هو الحكيم العليم في كل ما يأمر به وينهى عنه  وإن لم نعرف الحكمة، علينا أن نعمل بما أمرنا -جل وعلا- وإن لم نعرف الحكمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12015/الحكمة-من-الوضوء-من-اكل-لحم-الجزور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51906.mp3","categories":["نواقض الوضوء"]},{"id":13681,"question":"السائل هذا يقول: هل نزيف الدم من الأنف، وبشكل متكرر يبطل الوضوء حيث إنه ينزف أحيانًا خلال الوضوء نفسه، فهل أعيده من جديد؟ أفيدونا سماحة الشيخ.","title":"هل الرعاف ينقض الوضوء؟","answer":"الجواب: إذا كان قليلًا؛ يعفى عنه، وإن كان كثيرًا؛ فالأحوط الإعادة، إعادة الوضوء، وأما إن كان قليلًا يعفى عنه، والحمد لله؛ لأن في نقض الوضوء بالرعاف الكثير خلاف بين العلماء، فإذا كثر الدم؛ فالأحوط أن تعيد الوضوء إذا وقف الدم، وأما إن كان قليلًا؛ يعفى عنه، تمسحه ويعفى عنه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12030/هل-الرعاف-ينقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51910.mp3","categories":["نواقض الوضوء"]},{"id":13777,"question":"من جدة هذه رسالة بعث بها المستمع (م. س. س.أ) أخونا له جمع من الأسئلة من بينها سؤال عن نظافة الطفل الرضيع، هل يؤثر ذلك على وضوء أمه؟","title":"هل يؤثر مس عورة الطفل في الوضوء؟","answer":"الجواب: نعم إذا مست فرجه فإنها تتطهر ينتقض وضوءها، إذا مست فرجه ذكره أو قبل الأنثى أو حلقة الدبر فإن هذا ينقض الوضوء إذا كانت على وضوء تعيد الوضوء، كالرجل وكالمرأة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12160/هل-يوثر-مس-عورة-الطفل-في-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60108.mp3","categories":["نواقض الوضوء","قضايا المرأة"]},{"id":14383,"question":"هل ملامسة النساء الأجنبيات يبطل الوضوء؟","title":"هل ملامسة النساء تبطل الوضوء؟","answer":"الجواب: الله يقول: أَوْ لامَسْتُمُ النِّسَاءَ [المائدة:6] اختلف العلماء فيها، قال بعضهم: المراد بالملامسة المس باليد عن شهوة، فهذا ينقض الوضوء مع الزوجة ومع غيرها، والصواب: أن الملامسة: الجماع، وأن قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ يعني: جامعتم النساء. أما اللمس بدون جماع لا يبطل الوضوء، هذا الصحيح، سواء عن شهوة أو عن غير شهوة لا يبطل الوضوء، لا مع الزوجة ولا مع غيرها، إذا لم يخرج شيء، أما إذا خرج مذي أو مني بطل، لكن إذا لم يخرج شيء إنما هو مجرد مس ولو بشهوة الصحيح أنه لا ينقض الوضوء؛ لأنه ثبت عن النبي ﷺ: أنه كان ربما قبل بعض نسائه، ثم صلى ولم يتوضأ، والتقبيل يكون عن شهوة وعن تلذذ، فكونه يقبل بعض نسائه ثم يصلي ولا يتوضأ يدل على أن المس لا ينقض الوضوء، وأن المراد بالملامسة الجماع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12864/هل-ملامسة-النساء-تبطل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55206.mp3","categories":["نواقض الوضوء"]},{"id":14647,"question":"الأخت السائلة التي رمزت لاسمها بـ (و. و. و) من الرياض، تقول في هذا  من زاد واجبًا من واجبات الصلاة عمدًا هل تبطل صلاته كمن زاد ركنًا عمدًا؟","title":"حكم زيادة واجب أو ركن في الصلاة عمدًا","answer":"الجواب: هذا فيه تفصيل: إذا زاد ركوعًا ثانٍ متعمدًا، أو سجودًا ثالثًا متعمدًا، هذا تبطل صلاته، أما إذا كرر التسبيح قال: سبحان ربي العظيم، كثيرًا، أو سبحان ربي الأعلى، هذا طيب ما فيه شيء.  أما إذا زاد ركنًا ما يشرع تكراره، أو واجبًا ما يشرع تكراره تبطل الصلاة، التشهد الأول واجب، فلو جلس في الثالثة، أو في الأولى متعمدًا ما هو بجلسة الاستراحة، بل يرى جلسة زائدة غير الاستراحة تبطل صلاته، أو زاد ركوعًا أو زاد سجودًا ثالثًا في الركعة، أو ركوعًا ثانيًا في الركعة، ومتعمدًا بطلت صلاته، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13135/حكم-زيادة-واجب-او-ركن-في-الصلاة-عمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55916.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":14951,"question":"إذا نزل الدم -تقول السائلة- من الفم أو الأنف فهل تبطل الصلاة؟ وهل يبطل الصيام والوضوء؟","title":"حكم الصلاة والصيام إذا خرج الدم من الأنف أو الفم","answer":"الجواب: إن كان شيئًا يسيرًا يعفى عنه، ولا تبطل به الصلاة، ولا الوضوء، شيء يخرج من الأنف قليل، أو من الأسنان، أو من اللثة، أو من الحلق، شيء يسير يعفى عنه.  أما إذا كان كثيرًا عرفًا، تبطل الصلاة، وعلى الإنسان أن يتوضأ من هذا الشيء ثم يعيد الصلاة إذا كانت فريضة، أما الشيء اليسير يعفى عنه. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13447/حكم-الصلاة-والصيام-اذا-خرج-الدم-من-الانف-او-الفم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56213.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":15169,"question":"هذه رسالة وردتنا من زوجة طبيب مسلم، تقول فيها: السلام عليكم ورحمة الله وبركاته، وبعد:زوجي بحكم عمله كطبيب نسائي يكشف على عورات النساء، مما يضطره إلى لمسهن، وهو يلبس قفازين نايلو، فهل إذا كان متوضئ ولمس عورة المرأة وهو يلبس القفاز ينتقض وضوءه أم لا؟","title":"حكم الوضوء من لمس العورة","answer":"الجواب: إذا لمس العورة من دون حائل[1] لا ينتقض، لا هو ولا غيره، إذا لمس الرجل عورته من وراء الإزار، أو من وراء السراويل؛ لا ينتقض وضوؤه، وهكذا المرأة إذا لمست عورتها من وراء الإزار، أو من وراء السراويل، لا تبطل الطهارة.  وهكذا الرجل الطبيب إذا لمس العورة دعت الحاجة إلى كشفه عن المرأة، وعلاج فرجها؛ فإنه إذا مس الفرج من دون حائل، لا ينتقض وضوؤه، بخلاف إذا مسه باللحم مس اللحم اللحم، فإنه ينتقض الوضوء، نعم.","link":"https://binbaz.org.sa/fatwas/13682/حكم-الوضوء-من-لمس-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65910.mp3","categories":["نواقض الوضوء","قضايا المرأة"]},{"id":15368,"question":"تقول هذه السائلة: نسمع كثيرًا أن من نام وهو على طهارة، وهو جالس ولو نومًا كثيرًا بأن الوضوء لا ينتقض، ما مدى صحة هذا الكلام سماحة الشيخ؟","title":"ما حكم وضوء من استغرق في النوم؟","answer":"الجواب: هذا غير صحيح، هذا الكلام ما هو بصحيح، متى نام نومًا مستغرقًا زال معه شعوره، سواء كان جالسًا أو مضطجعًا، بطل وضوؤه؛ لقوله ﷺ في الحديث الصحيح حديث صفوان بن عسال، يقول : \"كان النبي ﷺ يأمرنا أن لا ننزع خفافنا إلا من الجنابة، لكن يأمرنا أن نمسح على خفافنا، وأن لا ننزع خفافنا إلا من جنابة، ولكن من غائط وبول ونوم\" كان يأمرهم أن يمسحوا أو يتوضؤوا ويمسحوا على الخفاف من الغائط والنوم، ولم يفصل. فالنوم المستغرق ينقض الوضوء بلا شك، سواء كان جالسًا أو مضطجعًا أو ساجدًا أو قائمًا لهذا الحديث: \"ولكن من غائط وبول ونوم\". وروي عن النبي ﷺ أنه قال: من نام فليتوضأ في عدة روايات، لكن أصحها حديث صفوان، قال: \"كان يأمرنا أن لا ننزع خفافنا إلا من جنابة، ولكن من غائط وبول ونوم\" نعم، يأمرهم يمسحوا على الخفاف، ولا ينزعوها، لكن إذا أصابتهم الجنابة ينزعونها، ولكن يمسحون عند الوضوء من الغائط والبول والنوم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13871/ما-حكم-وضوء-من-استغرق-في-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49911.mp3","categories":["نواقض الوضوء"]},{"id":15669,"question":"مستمعة يمنية مقيمة في المملكة، تقول: أختكم في الإسلام لطيفة محمد أحمد، الأخت لطيفة تقول: سمعنا في هذا البرنامج أن لحم الجزور ينقض الوضوء، فهل علينا إعادة الوضوء كاملًا؟ وهل مرق الجزور ينقض الوضوء أيضًا؟ وهل إذا صلى الشخص بدون وضوء فهل صلاة هذا الشخص صحيحة أم يعتبر على طريقة غير صحيحة، أي: بعد أكل لحم الجزور؟جزاكم الله خيرًا.","title":"حكم الوضوء من لحم الإبل ومرقها ولبنها","answer":"الجواب: لحم الإبل ينقض الوضوء، وهو لحم الجزور؛ لأن النبي ﷺ أمر بالوضوء من لحم الإبل، وقال: توضؤوا من لحوم الإبل ولحومها الهبر، أما الكرش و.......، فهذه ليست داخلة فيه، والشحم كذلك، لكن إذا توضأ منه من باب الاحتياط فهو حسن.  أما اللبن والمرق فلا وضوء منهما، اللبن والمرق لا وضوء منهما، وإنما الوضوء من اللحم خاصة إذا أكله، يتوضأ وضوء الصلاة ليس فيه استنجاء، مثل من خرج منه الريح، يعني: يتمضمض ويستنشق ويغسل وجهه وذراعيه ويمسح رأسه وأذنيه ويغسل رجليه، ليس فيه استنجاء، الاستنجاء يكون من البول والغائط، أما خروج الريح والنوم ولحم الإبل ومس الفرج، فهذا ليس فيه إلا الوضوء، التمسح، يعني: غسل الأطراف الأربعة: غسل الوجه واليدين مع المرفقين مسح الرأس، مع الأذنين، غسل الرجلين مع الكعبين، في مس الفرج، وفي أكل لحم الإبل في النوم في خروج الريح، هذه ليس فيها إلا الوضوء فقط، الذي ليس فيه استنجاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14213/حكم-الوضوء-من-لحم-الابل-ومرقها-ولبنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70518.mp3","categories":["نواقض الوضوء"]},{"id":15860,"question":"هل لمس الرجل ليد الزوجة أو ليد المرأة الأجنبية عنه بغير قصد ناقض للوضوء؟","title":"من مس أمرأة هل ينتقض وضوؤه؟","answer":"الجواب: لا ينقض الوضوء، مس المرأة لا ينقض الوضوء، زوجته أو محرمه أو غيرهما لا ينقض الوضوء، إلا إذا خرج منه مني، أو خرج منه مذي، إذا خرج مذي يتوضأ، يغسل ذكره ويتوضأ، ذكره وأنثييه ويتوضأ، أو خرج مني بشهوة يغتسل -عليه غسل الجنابة-، أما إذا مسها، أو قبّل (زوجها) أو مسها، ولم يحصل شيء ما ينتقض وضوؤه. أما قوله تعالى: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به الجماع، جامعتم يعني، كنى به الرب عن الجماع، هذا الصواب، لمس المرأة لا ينقض الوضوء مطلقًا، هذا الصواب، سواءً عن شهوة، أو عن غير شهوة، هذا هو القول الحق.\nلكن لو لمسها، قبّل زوجته، أو لمسها، فخرج منه مذي، هذا يوجب الوضوء، يغسل ذكره وأنثييه ويتوضأ، أما إن أمنى -خرج مني، يعني: سبقته الشهوة- فهذا عليه غسل جنابة، والنبي ﷺ كان يقبل نساءه ويصلي ولا يتوضأ، كان يباشرهم ويقبلهم ويصلي ولا يتوضأ -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/14451/من-مس-امراة-هل-ينتقض-وضووه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57622.mp3","categories":["نواقض الوضوء"]},{"id":16023,"question":"إذا كان الإنسان على وضوء، وخرج من جسمه دم، هل يبطل وضوؤه؟","title":"هل خروج الدم يبطل الوضوء؟","answer":"الجواب: إن كان الدم يسيرًا كالجراحات اليسيرة، فالوضوء لايبطل، ووضوؤه صحيح، أما إن كان الدم كثيرًا، فاختلف العلماء في ذلك، منهم من رآه يبطل الوضوء، منهم من رأى هذه الجراحات تبطل الوضوء، ومنهم من رأى أنه لا يبطل الوضوء. يعني: الأحاديث في ذلك ليست صريحة، والصريح منها ليس بصحيح، فالأحوط للمؤمن إذا كان الدم كثيرًا أن يقضي الصلاة؛ خروجًا من الخلاف، واحتياطًا للدين، أما إن كان الدم يسيرًا، وخفيفًا، وقليلًا؛ يعفى عنه. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14656/هل-خروج-الدم-يبطل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74721.mp3","categories":["نواقض الوضوء"]},{"id":16321,"question":"رسالة وصلت من المستمع عبده محمد محسن راجح من اليمن تعز، يسأل فيها بعض الأسئلة، يقول في سؤاله الأول: هل تبطل الصلاة بعمل بعض المحرمات؟","title":"هل تبطل الصلاة بعمل بعض المحرمات؟","answer":"الجواب: هذا فيه تفصيل: إن كان عمل بعض المحرمات في الصلاة هذا يبطلها، مثلًا: يتكلم في الصلاة، أو يضحك في الصلاة، أو يسب أحدًا في الصلاة؛ هذا يبطل الصلاة. أما إن كان عنده معصية خارج الصلاة، عصى خارج الصلاة، فالمعصية خارج الصلاة لا تبطلها، لو كان عنده معصية، سب إنسانًا خارج الصلاة، أو اغتاب خارج الصلاة، أو بعد الصلاة ما يبطلها، أو والعياذ بالله قد زنى خارج الصلاة، أو شرب مسكرًا خارج الصلاة لا يبطلها إلا ما كان فيها، فإذا فعل فيها ما يبطلها من مبطلات الصلاة، من الكلام العمد، أو الضحك، أو العبث الكثير المتوالي، أو الأكل، أو الشرب هذا يبطلها، وأما معصية قبلها، أو بعدها لا تخرجه عن الإسلام، لا تبطلها إذا كانت قبلها، أو بعدها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15013/هل-تبطل-الصلاة-بعمل-بعض-المحرمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81012.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":16379,"question":"طيب إذا لبس الشخص جوربًا على وضوء، ثم انتقض الوضوء، وتوضأ، ومسح عليه، ثم خلعه، فهل يبقى على وضوؤه؟","title":"حكم الوضوء بعد خلع الجوارب","answer":"الجواب: إذا خلعه؛ بطل الوضوء، إذا خلعه بعد الحدث؛ بطل الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/15080/حكم-الوضوء-بعد-خلع-الجوارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58118.mp3","categories":["نواقض الوضوء"]},{"id":17032,"question":"يقول السائل: إذا مس الإنسان، أو صافح زوجته، هل ينتقض الوضوء؟","title":"حكم وضوء من مس زوجته","answer":"الجواب: الصواب أن مس المرأة لا ينقض الوضوء مطلقًا، سواءٌ زوجته، أو أخته، أو عمته، أو أمه، أما قوله سبحانه: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به الجماع، وقد ذهب بعض أهل العلم إلى أن مس المرأة ينقض مطلقًا، وبعضهم قال: مسها إذا كان بشهوة عن تلذذ ينقض. والصواب: أنه لا ينقض مطلقًا إلا إذا خرج منه شيء مذي، أو مني، وإلا فإنه لا ينقض، مجرد مس المرأة زوجته، أو غير زوجته الصواب أنه لا ينقض، وقد كان النبي يقبل بعض نسائه، ثم يصلي، ولا يتوضأ، اللهم صل وسلم عليه، أما قوله -جل وعلا-: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43] فالمراد به الجماع. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15816/حكم-وضوء-من-مس-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58710.mp3","categories":["نواقض الوضوء"]},{"id":17350,"question":"المستمع أحمد سليم مسلم مقيم بدولة الإمارات العربية المتحدة، بعث برسالة يسأل فيها عن الحركة في الصلاة، يقول: إن هناك أناسًا يقولون: إن الحركة في الصلاة تبطلها، وجهونا جزاكم الله خيرًا.","title":"ما حكم الحركة في الصلاة؟","answer":"الجواب: العبث في الصلاة لا يجوز إذا كثر، أما الشيء اليسير فيعفى عنه.. الشيء اليسير عرفًا يعفى عنه، ولكن إذا كثر، وتوالى أبطل الصلاة، فالواجب على المؤمن في صلاته، والمؤمنة الحرص على أسباب سلامتها، والحذر من أسباب بطلانها، والشيء اليسير يعفى عنه، مثل كونه عدل ثوبه، أو عمامته، أو مسح التراب أمام وجهه عند السجود مرة، أو مرتين، لا يضر صلاته، لكن الأفضل مرة واحدة؛ لقوله ﷺ في مثل هذا: مرة أو دع. فالمقصود: أن المؤمن يحرص على الخشوع، والإقبال على صلاته، والحضور فيها بقلبه، وترك العبث، والحركة غاية الحرص، قال الله سبحانه: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:2] . لكن إذا عبث يسيرًا ما يضر صلاته الحركة بأن أخذ شيئًا، أو طرحه، أو حك رأسه قليلًا، أو ما أشبه ذلك من الأشياء التي يفعلها الإنسان بعض الأحيان لا تضر صلاته، لكن إذا كثر العبث، وتوالت الحركات عرفًا؛ بطلت الصلاة، فينبغي الحذر. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16205/ما-حكم-الحركة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83405.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":17436,"question":"من المملكة الأردنية الهاشمية المستمعة: إيمان يوسف رسالة وضمنتها جمعًا من الأسئلة في أحدها تقول: هل لمس الزوج لزوجته، أو العكس يبطل الوضوء؟","title":"هل ينتقض الوضوء بلمس المرأة؟","answer":"الجواب: هذا فيه تفصيل: إذا كان اللمس ليس عن شهوة، أخذ منها شيئًا، أو ناولها شيئًا بدون شهوة؛ هذا لا يبطل الوضوء، وهكذا لو كان عن شهوة.. عن تلذذ، فالصواب أنه لا يبطل الوضوء أيضًا في أصح قولي العلماء، أما قوله -جل وعلا-: أَوْ لامَسْتُمُ النِّسَاءَ [المائدة:6] فالمراد بالآية: الجماع في أصح قولي العلماء، كما قال ابن عباس -رضي الله عنهما- وجماعة، ليس المراد اللمس باليد، وفي قراءة: أو لمستم فالمراد باللمس والملامسة المراد بذلك في أصح قولي العلماء الجماع، نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ! .......","link":"https://binbaz.org.sa/fatwas/16313/هل-ينتقض-الوضوء-بلمس-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83615.mp3","categories":["نواقض الوضوء"]},{"id":17535,"question":"من الأردن من ضمن أسئلة هذا السائل يقول: ما هي مقدار الحركة التي تبطل الصلاة وما هي أقسامها، وما توجيهكم سماحة الشيخ للذين يكثرون الحركة في الصلاة؟","title":"حكم الإكثار من الحركة في الصلاة","answer":"الجواب: الحركة اليسيرة عرفًا لا تبطل الصلاة، لكن المشروع له السكون، والاطمئنان، والحذر من الحركات لقول الله جل وعلا: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ[المؤمنون:1-2]، فالواجب عليه أن يطمأن في ركوعه وسجوده وبين السجدتين، وبعد الاعتدال من الركوع يطمئن حتى يرجع كل فقر إلى مكانه، هذا ركن لا بد منه. أما الحركات اليسيرة يعفى عنها، فإذا كثرت وتوالت عرفًا فإنها تبطل الصلاة، إذا اعتقد أنها كثرت وتوالت فإنها تبطل الصلاة، ولكن الواجب عليه الحرص على عدم الحركة، ويعفى عن الشيء اليسير. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16467/حكم-الاكثار-من-الحركة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77515.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":17552,"question":"إذا أصابه رعاف بسيط تبلل منه شيء من أنفه ويده، هل يواصل الصلاة أم ينصرف؟","title":"ما يفعل من أصابه رعاف وهو في الصلاة؟","answer":"الجواب: نعم. إذا كان يسيرًا يواصل الصلاة لا ينقض الوضوء، أما إن كثر فالأفضل قطع الصلاة؛ لأن جمع من أهل العلم يراه ينقض الوضوء، فيقطعها ويتنظف، ثم أيضًا هو سوف ينجسه الدم نجاسة، إذا كثر يقطع الصلاة ويغسل ما أصابه أو يبدل ثيابه ثم يعيد الصلاة. نعم.\nالمقدم: جزاكم الله خيرًا، إذا خرج من الصلاة للرعاف الشديد وهو مستقبل القبلة، هل يجوز له بعد انتقائه من الرعاف أن يبني على ما سبق في صلاته؟\nالشيخ: لا، يعيدها من أولها، يستأنفها من أولها، يتنظف من الرعاف ويتوضأ إذا كان الرعاف كثير يتوضأ أحوط، يتوضأ وضوءًا جديدًا ويستأنفها من أولها، أما إن كان الرعاف قليلًا فإنه لا يقطع الصلاة يكملها لكن يجعل.. يأخذ ما حصل في منديل أو في طرف ردائه أو غترته ولا يضر إذا كان شيئًا يسيرًا، يكمل صلاته، أما إذا كان كثيرًا يقطعها ويزيل الدم يغسل الدم ويتوضأ أيضًا وضوء الصلاة، خروجًا من الخلاف أفضل له وأحوط ويعيد الصلاة من أولها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16499/ما-يفعل-من-اصابه-رعاف-وهو-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83818.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":17638,"question":"يسأل سؤالًا آخر عن الحركة في الصلاة هل تبطلها أو لا؟","title":"هل الحركة تبطل الصلاة؟","answer":"الجواب: الحركة فيها تفصيل: الحركة القليلة والحركة المتفرقة لا تبطلها، أما إذا كثرت وتوالت تبطلها عند العلماء، إذا كانت كثيرة عرفًا متوالية أبطلتها، أما التحديد بثلاث حركات لا أصل له لكن إذا تكرر كثيرًا في عمله بيديه أو مشي تقدم أو تأخر متوالي وكثر من ذلك بغير وجه شرعي يبطل الصلاة، أما إن كان له وجه شرعي مثل تقدم يسد فرجة في الصف مثلما تقدم النبي ﷺ في صلاة الكسوف لما عرضت عليه الجنة تقدم ولما رأى النار تأخر هذا لا بأس به، ومثلما تقدم صعد المنبر يصلي عليه ثم نزل، فإذا كان لمقصد شرعي لا بأس، أما تكرار الحركة وكثرتها متوالية من دون وجه شرعي فهذا يبطل الصلاة فالواجب الحذر من ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16565/هل-الحركة-تبطل-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84407.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":17750,"question":"هذا السائل يقول: هل مس الزوجة يبطل الوضوء؟الشيخ: أعد.المقدم: هل مس الزوجة أو لمس الزوجة يقول: هل لمس الزوجة يبطل الوضوء؟","title":"هل لمس الزوجة يبطل الوضوء؟","answer":"الجواب: الصواب أنه لا يبطل الوضوء، لا الزوجة ولا غيرها، إذا كان ما خرج شيء من الذكر من الفرج، مجرد مس أو قبلة، كان النبي ﷺ يقبل بعض نسائه ثم يصلي ولا يتوضأ، أما قوله سبحانه: أَوْ لامَسْتُمُ النِّسَاءَ [النساء:43]، فالمراد به الجماع، ما هو باللمس المراد بـ لامستم يعني: جامعتم النساء، أما لمسها وتقبيلها أو مصافحتها أو ما أشبه ذلك، هذا لا ينقض الوضوء مطلقًا، ولو عن شهوة، ولو عن تلذذ، الصواب أنه لا ينقض الوضوء، هذا هو الراجح من أقوال العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/16720/هل-لمس-الزوجة-يبطل-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59612.mp3","categories":["نواقض الوضوء"]},{"id":17921,"question":"هذا السائل أخوكم في الله محمد سيد حسن مصري ومقيم بالرياض يسأل عن خروج الدم أثناء الصلاة من الأنف هل يبطل الصلاة؟ وماذا يعمل المصلي في ذلك؟","title":"حكم خروج الدم أثناء الصلاة","answer":"الجواب: إذا خرج الدم من الأنف فلا يخلو إما يكن قليلا فيعفى عنه ويكمل صلاته، يعفى عن الدم اليسير من أنفه أو من أصل أسنانه أو من عينه الشيء اليسير، أو من يده أو رجله يعفى عنه، أما إن كان فاحشًا عرفًا يستفحش في نفسه فإنه يقطع الصلاة ويذهب ويغسل أنفه ويعيد الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/16944/حكم-خروج-الدم-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78011.mp3","categories":["نواقض الوضوء","النجاسات وإزالتها"]},{"id":18213,"question":"رجل توضأ، وذهب إلى المسجد، وهو في الطريق أصيب بالرعاف، فخرج من أنفه الدم، هل ينتقض وضوءه، والحال ما ذكر؟","title":"حكم من أصيب بالرعاف بعد الوضوء","answer":"الجواب: إذا كان كثيرًا، ينبغي له أن يتوضأ خروجًا من خلاف العلماء؛ لأن خروج الدم الكثير فيه خلاف بين أهل العلم، فإذا كان كثيرًا؛ فالأحوط له أن يتوضأ بعد ما ييبس، أما إن كان قليلًا فيعفى عنه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17255/حكم-من-اصيب-بالرعاف-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73119.mp3","categories":["نواقض الوضوء"]},{"id":18221,"question":"السائلة نائلة تقول وهي من الرياض تقول: إذا قمت بتنظيف طفلي، فهل يلزمني تجديد وضوئي بعد ذلك؟ أم أن طهارتي باقية؟","title":"حكم الوضوء من تطهير وتنظيف الطفل","answer":"الجواب: إذا كان التجديد فيه مس العورة ينتقض الوضوء؛ فإذا مست المرأة عورة طفلها انتقضت الطهارة، كما لو مست عورتها هي، فعليها تجديد الوضوء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17266/حكم-الوضوء-من-تطهير-وتنظيف-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78210.mp3","categories":["نواقض الوضوء"]},{"id":18238,"question":"يقول السائل من السودان: سمعت بأنه إذا كان الشخص متوضئ وأكل من لحم الإبل قبل الصلاة بأن الوضوء ينتقض فهل هذا صحيح، ولماذا ينتقض الوضوء من لحم الإبل؟","title":"وجوب الوضوء من أكل لحم الإبل","answer":"الجواب: نعم إذا توضأ وأكل من لحم الإبل أمره النبي ﷺ بالوضوء قال ﷺ: توضئوا من لحوم الإبل، فالرسول ﷺ أمر بالوضوء منها كما أمر بالوضوء من مس الفرج، ومن الريح التي تخرج من الدبر، ومن البول والغائط فالحكمة لله جل وعلا، هو الحكيم العليم  والرسول ﷺ مبلغ يبلغنا عن الله ، فعلينا أن نمتثل وإن لم نعرف العلة .. علينا أن نطيع الله ورسوله، فإذا إنسان أكل من لحم الإبل يتوضأ كما أمره النبي ﷺ، وإذا أحدث الريح أو البول أو الغائط كذلك، لكن مع البول والغائط يستنجي زيادة، يستنجي ثم يتوضأ، أما الريح ومس الفرج فهذا وضوء فقط، تمسح، غسل الوجه واليدين ومسح الرأس وغسل الرجلين، أما البول والغائط فلا بد من الاستنجاء قبل الوضوء.\nالمقصود أن العبد عليه الامتثال والطاعة، وإن لم يعرف الحكمة. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/17292/وجوب-الوضوء-من-اكل-لحم-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78224.mp3","categories":["نواقض الوضوء"]},{"id":18268,"question":"هل تنظيف الطفل والتغيير له ينقض الوضوء، إذا أجريت ذلك وكنت على وضوء؟","title":"حكم مس عورة الطفل","answer":"الجواب: نعم، إذا مس الفرج، إذا نظفت المرأة طفلها ومست فرجه انتقض الوضوء، كما لو مست فرجها. المقدم: حتى ولو كان دون البلوغ؟ الشيخ: ولو، النص عام.","link":"https://binbaz.org.sa/fatwas/17317/حكم-مس-عورة-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91004.mp3","categories":["نواقض الوضوء"]},{"id":18279,"question":"رسالة وصلت إلى البرنامج من جدة وباعثها أحد الإخوة: عثمان -لا أدري ما هو الاسم الثاني غير واضح- يبدو أنه سوداني الجنسية من خطه، يسأل -سماحة الشيخ- ويقول: إنني قرأت أن استتار العقل بسكر ينقض الوضوء، لكن هناك من يسكر -كما يقول- ولا يستتر عقله، هل ينتقض وضوءه؟","title":"مسألة انتقاض الوضوء بالسكر","answer":"الجواب: هذا فيه تفصيل: النوم: إذا استثقل الإنسان في نومه وذهب شعوره ينقض الوضوء، بنص السنة عن النبي ﷺ، فإذا أصيب الإنسان بما يغطي عقله، من سكر أو غشية أو إغماء فإنه ينتقض وضوءه؛ لأنه مظنة الحدث كالنوم، فالغشية التي تصيب الناس وهي الإغماء بسبب بعض الحوادث، أو صرع يصرع الإنسان حتى يغمى عليه، أو يشرب مسكرًا يذهب بعقله، هذه عليه الوضوء. أما إذا كان المسكر ما ذهب بعقله، بأن كان شيئًا يسيرًا، أو بأن كان قد اعتاد هذا الشيء فلا يسكر منه، ولا يذهب عقله؛ ما ينتقض وضوءه. الضابط: زوال العقل، فإذا زال عقله بإغماء، أو نوم، أو شرب مسكر، أو حبوب أزالت عقله، فإنه ينتقض وضوءه، فأما إذا كان يعقل ما يخرج منه، ولم يذهب عقله بهذه الحبوب أو بهذا الشراب.. من يعقل ما خرج منه من ريح أو بول؛ فإنه لا ينتقض وضوءه، فالحكم يدور مع بقاء العقل، إن بقي العقل فلا ينتقض الوضوء، وإن زال بسبب هذا الإغماء أو النوم أو السكر، فإنه يكون منتقض الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/17328/مسالة-انتقاض-الوضوء-بالسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91015.mp3","categories":["نواقض الوضوء"]},{"id":18406,"question":"يسأل سماحتكم سؤالًا آخر فيقول: هل مس الفرج دون حائل ينقض الوضوء ولو بدون شهوة؟","title":"حكم مس الفرج من غير حائل","answer":"الجواب: مس الفرج ينقض الوضوء إذا كان من غير حائل مس اللحم باللحم، ولو بدون شهوة، هذا هو الصواب؛ لأن الرسول ﷺ بين أنه ينقض الوضوء ولم يشترط الشهوة، فقال ﷺ: من مس ذكره فليتوضأ، وقال عليه الصلاة والسلام: أيما رجل أفضى بيده إلى فرجه ليس دونهما ستر فقد وجب عليه الوضوء، وأيما امرأة أفضت بيدها إلى فرجها ليس دونها ستر فقد وجب عليها الوضوء، ولم يشترط الشهوة، فدل ذلك على أن مس الفرج ينقض الوضوء مطلقًا بشهوة وبغير شهوة، سواء كان الرجل أو المرأة. إذا مس الرجل فرجه أو فرج امرأته أو فرج الطفل انتقض الوضوء، وهكذا المرأة إذا مست فرجها أو فرج زوجها أو فرج أطفالها انتقض الوضوء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. الواقع سماحة الشيخ يغفل كثير من الأمهات عن هذا الحكم. الشيخ: لا هذا مهم. نعم. المقدم: إذًا على الأم إذا طهرت أولادها وهي متوضئة عليها أن تعيد الوضوء. الشيخ: نعم إذا مست فروجهم. نعم، ذكوراً كانوا أو إناثاً. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17478/حكم-مس-الفرج-من-غير-حاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73302.mp3","categories":["نواقض الوضوء"]},{"id":18446,"question":"لماذا أكل لحم الإبل ينقض الوضوء؟","title":"سبب نقض لحم الإبل للوضوء","answer":"الجواب: الله أعلم، المعروف عند أكثر الفقهاء أنه تعبدي وأنه غير معلوم الحكمة والعلة، وأن الله سبحانه شرع لنا أن نتوضأ من لحوم الإبل والله أعلم بالحكمة والعلة في ذلك، قال بعض أهل العلم: إنها خلقت من الشياطين، وإن لها نفورًا يشبه حال الشياطين إذا استنفرت، وأن هذا من أجل أن لحومها تسبب شيئًا من القسوة وشيئًا من الشيطنة فيكون في الوضوء إطفاء لذلك، ولكن ليس هذا بأمر واضح ولا أعلم دليلًا واضحًا عليه، فالأقرب ما قاله الأكثرون أنه تعبدي والله سبحانه هو الأعلم بالحكمة والعلة في ذلك. والمؤمن عليه أن يمتثل أمر الله ورسوله وإن لم يعرف الحكمة، كما أنا نصلي الظهر أربعًا في الإقامة والعصر أربعًا والعشاء أربعًا والمغرب ثلاثًا والفجر ثنتين، وليس عندنا علم يقيني بالحكمة في جعلها أربعًا أي: الظهر والعصر والعشاء والمغرب ثلاثًا والفجر ثنتين، ففي الإمكان أن يفرضها الله  لو شاء تكون الظهر ثمانًا أو سبعًا أو ستًا، وهكذا العصر والعشاء، وفي الإمكان أن تكون المغرب بدل ثلاث خمسًا.. وهكذا فلله الحكمة البالغة  فيما فرض وعين جل وعلا. وهكذا فرضه رمضان في شهر واحد وإن كان العلة في الجملة التخفيف على الأمة لكن لا نعلم الحكمة العينية في جعل رمضان فرضًا دون غيره من الشهور وكونه شهرًا كاملًا، لو شاء ربنا لجعله خمسة عشر يومًا أو عشرين يومًا، فلله الحكمة البالغة في تخصيص هذا الشهر، وهكذا أشياء كثيرة من العبادات لا نعلم علتها وحكمتها. نعم.","link":"https://binbaz.org.sa/fatwas/17550/سبب-نقض-لحم-الابل-للوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86510.mp3","categories":["نواقض الوضوء"]},{"id":18718,"question":"يقول السائل: نحن من سكان الريف حيث يكثر الماء، وتوجد الزراعة، ويترتب على ذلك انتشار البعوض خاصة في فصل الصيف، وعندما نؤدي الصلوات لصلاة المغرب والعشاء والفجر، فإننا نتأذى من لدغ البعوض، وإذا تركناه يلدغنا انشغلنا به عن الصلاة، ولم نتدبر القراءة، ولا التسبيح، وإذا دفعناه ترتب على ذلك حركة كثيرة في الصلاة، وأدى إلى قتل كثير من هذا البعوض، ونحن في الصلاة، فما حكم الشرع في نظركم سماحة الشيخ؟ وما توجيهكم لنا؟","title":"كثرة الحركة لدفع البعوض أثناء الصلاة","answer":"الجواب: المشروع التحمل والصبر، والعلاج قبل الصلاة، كونه يعالج محل الصلاة بالمبيدات التي تبيد هذا البعوض حتى يكون في وقت الصلاة قد استراح، حتى لا يشتغل بالبعوض، وبالنسبة للحركة يسيرة يعفى عنها، الشيء اليسير في الصلاة يعفى عنه، لكن كون المصلين يشتغلون بالباعوض شغلًا كثيرًا هذا لا يجوز، الواجب التصبر والتحمل، إلا إذا تيسر ما يبيده قبل الصلاة، يستعمل ما يبيده من المبيدات حتى يكون المصلون في وقت الصلاة مستريحين من شره. والحركة اليسيرة التي مثل كونه يغطي قدميه عن البعوض؛ كونه يغطي يديه عن البعوض ببشته أو بغترته ما يضر هذا الحمد لله، الشيء اليسير يعفى عنه، النبي ﷺ صلى ذات يوم وهو حامل أمامة بنت زينب، إذا قام حملها، وإذا سجد وضعها، وصلى وهو على المنبر يصعد وينزل -عليه الصلاة والسلام- فالحركة اليسيرة، وفي صلاة الكسوف صلى بالناس، فلما عرضت عليه الجنة تقدم، ولما عرضت له النار تأخر، وتأخر الناس، فهذه الأشياء التي تعرض للإنسان خفيفة يعفى عنها. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17844/كثرة-الحركة-لدفع-البعوض-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78905.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":18846,"question":"يسأل أخونا ويقول: رجل يصلي فتحرك ثلاث حركات متتالية، فهل تبطل صلاته كحك الرأس أو الأنف، أو ما شابه ذلك؟","title":"ضابط الحركة التي تبطل الصلاة","answer":"الجواب: ليس على هذا دليل ولا تبطل الصلاة بذلك، لكن ينبغي للمؤمن أن يجتهد في السكون في الصلاة والخشوع، وعدم العبث، وعدم الحركة، إلا من حاجة، على مراعاة القلة، وعدم الإكثار، وقد ذكر العلماء -رحمهم الله-: أن الحركة الكثيرة في الصلاة متوالية تبطلها من غير تحديد. أما التحديد بثلاث فهو قول ضعيف، لا دليل عليه، ولا تبطل به الصلاة، فلو حرك يده ثلاثًا، أو حك رأسه ثلاثًا، أو ما أشبه ذلك لم تبطل صلاته بذلك، وهكذا إذا كانت الحركة مفرقة، فإنها لا تبطل الصلاة. فقد ثبت عنه ﷺ أنه صلى على المنبر، ثم نزل فسجد في أصل المنبر، ثم صعد فقرأ على المنبر، وركع عليه فلما سلم قال: إنما فعلت هذا لتأتموا بي؛ ولتعلموا صلاتي وثبت عنه ﷺ: «أنه صلى وهو حامل أمامة بنت زينب ابنة بنته أمامة بنت زينب -رضي الله عنها- فإذا سجد وضعها، وإذا قام حملها» -عليه الصلاة والسلام- هذه الحركة لم تبطل بها الصلاة؛ لأنها مفرقة. وهكذا ثبت عنه ﷺ في صلاة الكسوف أنه لما عرضت عليه الجنة تقدم وتقدمت الصفوف، وأراد أن يتناول منها عنقودًا، فلم يتيسر ذلك، ولم يمكن من ذلك؛ ولما عرضت عليه النار -عليه الصلاة والسلام- تأخر وتأخرت الصفوف فدل ذلك على أن هذه الحركة وأشباهها لا تبطل الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17971/ضابط-الحركة-التي-تبطل-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92111.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":19040,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها مجموعة من الأسئلة، المستمع هو (أ. ح) من محافظة الشرقية جمهورية مصر العربية، في سؤاله الأول يقول: إذا مس الإنسان فرجه أو فرج أحد أطفاله مثلًا أو الأم لامست أحد أطفالها هل يجب عليها إعادة الوضوء؟","title":"حكم وضوء من مس عورته أو عورة غيره","answer":"الجواب: نعم إذا مس الإنسان فرجه مباشرة يعني: مس اللحم اللحم، مس الفرج: الذكر أو الدبر انتقض الوضوء، وهكذا المرأة إذا مست فرجها أو فرج بعض أولادها انتقض الوضوء؛ لقوله ﷺ: من مس ذكره فليتوضأ ولقوله عليه الصلاة والسلام: من أفضى بيده إلى فرجه ليس دونهما ستر فقد وجب عليه الوضوء فإذا مسه مباشرة فإنه ينتقض الوضوء. أما إذا كان من وراء الثياب، من وراء الإزار، من وراء السراويل فلا يضر، وإنما يضر إذا مس اللحم اللحم، مست يده الفرج، وليس دونهما حائل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18207/حكم-وضوء-من-مس-عورته-او-عورة-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92803.mp3","categories":["نواقض الوضوء"]},{"id":19064,"question":"هذا سائل للبرنامج يا سماحة الشيخ أرسل بمجموعة من الأسئلة يقول في سؤاله الأول: ما الحكمة بأن لحم الإبل من نواقض الوضوء؟","title":"الحكمة في أن لحم الإبل ينقض الوضوء","answer":"الجواب: الله أعلم، علينا أن نستجيب للرسول، وأن نمتثل وإن لم نعرف الحكمة، فالله لا يأمر إلا لحكمة  هو الحكيم العليم، وقد أمرنا الرسول ﷺ أن نتوضأ من لحوم الإبل فعلينا الامتثال. نعم.","link":"https://binbaz.org.sa/fatwas/18274/الحكمة-في-ان-لحم-الابل-ينقض-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88330.mp3","categories":["نواقض الوضوء"]},{"id":19412,"question":"أختنا تسأل وتقول: ما الحكم إذا دعست قدمي على نجاسة بعد انتهائي من الوضوء، هل أغسل القدم وحدها؟ أم أعيد الوضوء؟","title":"حكم من وطئ نجاسة بقدمه وهو على وضوء","answer":"الجواب: إذا كانت النجاسة رطبة كالبول والعذرة الرطبة فعليك أن تغسل القدم فقط، ولا يعاد الوضوء، إنما تغسل القدم التي أصابها النجاسة، أما إن كانت النجاسة يابسة والقدم يابسة فليس عليك شيء، إذا كانت القدم يابسة والنجاسة يابسة لا يضر، أما إذا كانت النجاسة رطبة أو القدم رطبة فإن عليك أن تغسلي ما أصاب القدم فقط، والوضوء صحيح، والله المستعان. المقدم: بارك الله فيكم، الله المستعان.","link":"https://binbaz.org.sa/fatwas/18639/حكم-من-وطى-نجاسة-بقدمه-وهو-على-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93608.mp3","categories":["نواقض الوضوء","قضايا المرأة"]},{"id":19449,"question":"يسأل سماحتكم عن حكم الضحك في الصلاة، وهل من ضحك في الصلاة هل عليه إعادة؟","title":"حكم الضحك في الصلاة","answer":"الجواب: الضحك في الصلاة يبطلها إجماعًا بإجماع أهل العلم، إذا ضحك في الصلاة بطلت، وهكذا لو تكلم عمدًا؛ بطلت صلاته إلا إذا كان جاهلًا أو ناسيًا، فلا تبطل الصلاة بالكلام الناسي وكلام الجاهل، لكن الضحك يبطلها؛ لأنه تلاعب بها تلاعب وسخرية، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18691/حكم-الضحك-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74017.mp3","categories":["نواقض الوضوء","مبطلات الصلاة"]},{"id":19696,"question":"سمعت أن دخول المقابر يفسد الوضوء فهل هذا صحيح؟ أفيدونا جزاكم الله عنا خيرًا.","title":"هل دخول المقابر ينقض الوضوء؟","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/20349/هل-دخول-المقابر-ينقض-الوضوء","audio":"","categories":["نواقض الوضوء"]}]
